#[cfg(windows)]
fn demo_recording_timestamp() -> String {
    #[repr(C)]
    struct WinSystemTime {
        year: u16,
        month: u16,
        day_of_week: u16,
        day: u16,
        hour: u16,
        minute: u16,
        second: u16,
        milliseconds: u16,
    }
    #[link(name = "Kernel32")]
    extern "system" {
        fn GetLocalTime(system_time: *mut WinSystemTime);
    }
    let mut local = std::mem::MaybeUninit::<WinSystemTime>::uninit();
    unsafe {
        GetLocalTime(local.as_mut_ptr());
        let local = local.assume_init();
        format!(
            "{:04}-{:02}-{:02}_{:02}-{:02}-{:02}",
            local.year, local.month, local.day, local.hour, local.minute, local.second
        )
    }
}

#[cfg(not(windows))]
fn demo_recording_timestamp() -> String {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |duration| duration.as_secs())
        .to_string()
}

/// A value in `[0, 1)` for gameplay choices that stock JKA makes with `rand()`.
fn random_unit() -> f32 {
    let nanos = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map_or(0, |duration| duration.as_nanos());
    let mut x = (nanos as u64) ^ ((nanos >> 64) as u64) ^ 0x9E37_79B9_7F4A_7C15;
    x ^= x >> 30;
    x = x.wrapping_mul(0xBF58_476D_1CE4_E5B9);
    x ^= x >> 27;
    x = x.wrapping_mul(0x94D0_49BB_1331_11EB);
    x ^= x >> 31;
    (x >> 40) as f32 / (1u64 << 24) as f32
}

fn normalize_cfg_qpath(name: &str) -> Result<PathBuf, String> {
    let name = name.trim().trim_matches('"');
    if name.is_empty() {
        return Err("config filename is empty".to_owned());
    }
    let mut path = PathBuf::from(name.replace('\\', "/"));
    if path.extension().is_none() {
        path.set_extension("cfg");
    }
    if !path
        .extension()
        .is_some_and(|ext| ext.to_string_lossy().eq_ignore_ascii_case("cfg"))
    {
        return Err("Only the .cfg extension is supported".to_owned());
    }
    if path.components().any(|component| {
        matches!(
            component,
            std::path::Component::ParentDir
                | std::path::Component::RootDir
                | std::path::Component::Prefix(_)
        )
    }) {
        return Err("config path must stay inside the active game directory".to_owned());
    }
    Ok(path)
}

const MAX_CONSOLE_COMMAND_BUFFER_BYTES: usize = 128 * 1024;
const MAX_CONSOLE_COMMANDS_PER_FRAME: usize = 4096;

fn split_console_script(text: &str) -> Vec<String> {
    let chars: Vec<char> = text.chars().collect();
    let mut out = Vec::new();
    let mut current = String::new();
    let mut quoted = false;
    let mut line_comment = false;
    let mut block_comment = false;
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        let next = chars.get(i + 1).copied();
        if line_comment {
            if c == '\n' || c == '\r' {
                line_comment = false;
                let command = current.trim();
                if !command.is_empty() {
                    out.push(command.to_owned());
                }
                current.clear();
            }
            i += 1;
            continue;
        }
        if block_comment {
            if c == '*' && next == Some('/') {
                block_comment = false;
                i += 2;
            } else {
                i += 1;
            }
            continue;
        }
        if !quoted && c == '/' && next == Some('/') {
            line_comment = true;
            i += 2;
            continue;
        }
        if !quoted && c == '/' && next == Some('*') {
            block_comment = true;
            i += 2;
            continue;
        }
        if c == '"' {
            quoted = !quoted;
            current.push(c);
            i += 1;
            continue;
        }
        if !quoted && (c == ';' || c == '\n' || c == '\r') {
            let command = current.trim();
            if !command.is_empty() {
                out.push(command.to_owned());
            }
            current.clear();
            i += 1;
            continue;
        }
        current.push(c);
        i += 1;
    }
    let command = current.trim();
    if !command.is_empty() {
        out.push(command.to_owned());
    }
    out
}

