#[derive(Debug, Clone, Copy)]
struct DemoTimeline {
    wall_anchor: Instant,
    demo_anchor_ms: f64,
    rate: f64,
    resume_rate: f64,
}

impl DemoTimeline {
    fn new(first_server_time: i32, now: Instant) -> Self {
        Self {
            wall_anchor: now,
            demo_anchor_ms: f64::from(first_server_time),
            rate: 1.0,
            resume_rate: 1.0,
        }
    }

    /// Continuous presentation time. Keep the demo clock at sub-millisecond
    /// precision even though JKA protocol/snapshot times are integer ms. This
    /// avoids quantizing multiple high-FPS render frames onto the same sample.
    fn target_time_ms(self, now: Instant) -> f64 {
        let elapsed_ms = now.saturating_duration_since(self.wall_anchor).as_secs_f64() * 1000.0;
        let value = self.demo_anchor_ms + elapsed_ms * self.rate;
        value.clamp(f64::from(i32::MIN), f64::from(i32::MAX))
    }

    fn set_rate(&mut self, now: Instant, rate: f64) {
        // Preserve the exact fractional position when pausing or changing rate;
        // otherwise every control change can inject a <= 1 ms presentation hop.
        self.demo_anchor_ms = self.target_time_ms(now);
        self.wall_anchor = now;
        self.rate = rate;
        if rate > 0.0 {
            self.resume_rate = rate;
        }
    }

    fn seek(&mut self, now: Instant, demo_time_ms: f64) {
        self.demo_anchor_ms = demo_time_ms.clamp(f64::from(i32::MIN), f64::from(i32::MAX));
        self.wall_anchor = now;
    }

    fn toggle_pause(&mut self, now: Instant) {
        if self.rate == 0.0 {
            self.set_rate(now, self.resume_rate.max(0.01));
        } else {
            self.set_rate(now, 0.0);
        }
    }
}

/// One CGame lifetime (OpenJK CL_InitCGame .. CL_ShutdownCGame) fed either by
/// a demo file or by a live connection. Both go through the same snapshot
/// transition, event, and presentation path.
/// Live prediction's display-only provisional state, used by presentation and
/// camera for sub-command-frame smoothness.
struct LivePredictionFrame {
    display: jka_protocol::server::PlayerState,
    /// The state presented on the previous frame (CG_TransitionPlayerState's ops).
    previous_display: jka_protocol::server::PlayerState,
    error: [f32; 3],
}

fn snapshot_owns_playerstate_events(
    live: bool,
    local: bool,
    no_predict: bool,
    synchronous_clients: bool,
    player_state: &jka_protocol::server::PlayerState,
) -> bool {
    const PMF_FOLLOW: i32 = 4096;
    local
        || !live
        || no_predict
        || synchronous_clients
        || player_state.field_i32("pm_flags").unwrap_or(0) & PMF_FOLLOW != 0
}

