struct DemoGamestateProbe {
    fs_game: Vec<u8>,
    map_name: String,
}

/// Read only as far as the first gamestate, mirroring CL_PlayDemo_f's
/// pre-CA_PRIMED message pump. Besides fs_game, retain the map name so the
/// loading-information screen can become authoritative before CGame assets are
/// built or any old rendered world is replaced.
fn probe_demo_gamestate(bytes: &[u8]) -> Result<DemoGamestateProbe, String> {
    let mut reader = DemoReader::new(Cursor::new(bytes));
    let mut decoder = ServerMessageDecoder::new();
    let mut setgame = Vec::new();
    let mut messages = 0usize;
    loop {
        let record = reader
            .next_record()
            .map_err(|error| format!("DEMO GAMESTATE PROBE FRAMING ERROR: {error}"))?
            .ok_or_else(|| "DEMO REACHED EOF BEFORE GAMESTATE".to_owned())?;
        let packet = decoder.parse_packet(record.sequence, &record.payload).map_err(|error| {
            format!(
                "DEMO GAMESTATE PROBE PROTOCOL ERROR: message {messages} sequence {}: {error}",
                record.sequence
            )
        })?;
        messages += 1;
        for event in &packet.events {
            match event {
                ServerMessageEvent::SetGame(game) => setgame = game.clone(),
                ServerMessageEvent::Gamestate { .. } => {
                    let system_game = decoder
                        .configstrings
                        .get(&jka_protocol::session::CS_SYSTEMINFO)
                        .and_then(|info| jka_protocol::commands::info_value(info, b"fs_game"))
                        .unwrap_or_default();
                    let fs_game = if system_game.is_empty() {
                        setgame
                    } else {
                        system_game.to_vec()
                    };
                    let map_name = decoder
                        .map_name()
                        .ok_or_else(|| "DEMO GAMESTATE HAS NO MAPNAME".to_owned())?;
                    return Ok(DemoGamestateProbe { fs_game, map_name });
                }
                _ => {}
            }
        }
        if messages >= 4096 {
            return Err("DEMO GAMESTATE PROBE DID NOT REACH A GAMESTATE".to_owned());
        }
    }
}


impl GameSession {
    /// Push the app-level client options every presenter of this session reads.
    fn apply_client_options(
        &mut self,
        screen_shake: u8,
        game: crate::config::GameOptions,
        footprints: FootprintMode,
        japro: crate::japro_cg::JaproCgame,
        plugin_disable: i32,
    ) {
        self.screen_shake_level = screen_shake;
        self.weapon_fx.set_footprint_mode(footprints);
        self.weapon_fx.set_gib_level(game.blood);
        self.weapon_fx.set_score_plums(game.score_plums);
        self.player_presenter.set_gore_limit(usize::from(game.g2_marks));
        self.player_presenter.set_footstep_level(game.footsteps, footprints != FootprintMode::Off);
        self.player_presenter.set_japro_options(japro);
        self.client_game.set_plugin_disable(plugin_disable);
        self.japro_cg = japro;
    }

    /// jaPRO `DF_RaceTimer`: refresh this frame's race readout.
    fn update_race_timer(&mut self, now: i32, predicted: Option<&jka_protocol::server::PlayerState>) {
        let ps = predicted.or_else(|| self.current_snapshot.as_ref().map(|snapshot| &snapshot.player_state));
        let ui = ps.and_then(|ps| {
            let racemode = self.client_game.is_japro() && ps.stats[crate::japro_cg::STAT_RACEMODE] != 0;
            let duel_time = ps.field_i32("duelTime").unwrap_or(0);
            let speed = ps
                .field_f32("velocity[0]")
                .zip(ps.field_f32("velocity[1]"))
                .map_or(0.0, |(x, y)| x.hypot(y));
            // `speed` is a float netfield; reading it as i32 yields its raw bits.
            let move_speed = ps.field_f32("speed").unwrap_or(250.0);
            self.race_stats.frame(&self.japro_cg, racemode, duel_time, now, speed, move_speed)
        });
        self.race_timer_ui = ui;
    }

    /// The equipped sabers CG_PredictPlayerState's Pmove sees through
    /// BG_MySaber (`cgs.clientinfo[clientNum].saber[]`). Re-derived only when
    /// the client's userinfo configstring changes.
    fn predicted_saber_movement(&mut self, client_num: i32) -> [jka_movement::SaberMovementInfo; 2] {
        let Ok(client) = usize::try_from(client_num) else {
            return Default::default();
        };
        let raw = crate::cgame::CS_PLAYERS
            .checked_add(client as u16)
            .and_then(|index| self.client_game.configstring(index))
            .unwrap_or_default();
        if let Some((key, cached)) = &self.predicted_saber_cache {
            if key.as_slice() == raw {
                return *cached;
            }
        }
        let key = raw.to_vec();
        let loadout = self
            .client_game
            .client_info(client, &self.siege_classes)
            .map(|info| {
                self.player_presenter.saber_movement_loadout(
                    [&info.saber_name, &info.saber2_name],
                    true,
                )
            })
            .unwrap_or_default();
        self.predicted_saber_cache = Some((key, loadout));
        loadout
    }

    fn new(
        qpath: String,
        source: String,
        bytes: Vec<u8>,
        siege_classes: Vec<jka_assets::siege::SiegeClassVisual>,
        player_presenter: PlayerPresenter,
        entity_presenter: EntityPresenter,
        weapon_fx: crate::cgame::weapon_fx::WeaponFx,
        forced_player_models: Option<ForcedPlayerModels>,
    ) -> Self {
        let demo_bytes: Arc<[u8]> = Arc::from(bytes);
        let demo_index = if demo_bytes.is_empty() {
            None
        } else {
            match build_demo_index(&demo_bytes) {
                Ok(index) => Some(index),
                Err(error) => {
                    eprintln!("DEMO INDEX WARNING: {error}");
                    None
                }
            }
        };
        Self {
            live: false,
            local: false,
            live_snapshots: VecDeque::new(),
            qpath,
            source,
            reader: DemoReader::new(Cursor::new(demo_bytes.clone())),
            demo_bytes,
            demo_index,
            decoder: ServerMessageDecoder::new(),
            messages: 0,
            snapshots: 0,
            phase: SessionPhase::WaitingForMap,
            map_name: None,
            pending_snapshot: None,
            current_snapshot: None,
            next_snapshot: None,
            first_server_time: None,
            timeline: None,
            eof: false,
            seeking_demo: false,
            suppress_audio: false,
            demo_hidden_view_client: None,
            player_position: None,
            client_game: ClientGameState::new(),
            siege_classes,
            presented_entities: Vec::new(),
            audio_followed_entity: None,
            predicted_saber_cache: None,
            forced_player_models,
            player_presenter,
            entity_presenter,
            event_presenter: EventPresenter::default(),
            pending_out_of_ammo: Vec::new(),
            view_offset_z: 0.0,
            item_pickup: None,
            timer_bar: None,
            reward_active: None,
            reward_queue: VecDeque::new(),
            force_flash_until: None,
            item_pickup_until: HashMap::new(),
            pending_weapon_select: Vec::new(),
            screen_shake_level: 1,
            japro_cg: crate::japro_cg::JaproCgame::default(),
            race_stats: crate::japro_cg::RaceStats::default(),
            race_timer_ui: None,
            lagometer: crate::lagometer::Lagometer::default(),
            map_change: false,
            vote_ui: None,
            follow_fastest: crate::japro_cg::FollowFastest::default(),
            sound_presenter: None,
            weapon_fx,
            fx_draws: Vec::new(),
            fx_lights: Arc::new(Vec::new()),
            fx_blades: Arc::new(Vec::new()),
            fx_surfaces: Arc::new(Vec::new()),
            screen_fx: Arc::new(Vec::new()),
            dynamic_models: Arc::new(Vec::new()),
            client_perf: ClientFramePerf::default(),
            inline_models: Arc::new(Vec::new()),
            logged_entity_summary: false,
            logged_dispatch_summary: false,
            event_debug_lines: VecDeque::with_capacity(256),
            event_stats: BTreeMap::new(),
            event_suppressed_duplicate: 0,
            event_suppressed_zero: 0,
        }
    }

    fn push_event_debug_line(&mut self, line: String) {
        if self.event_debug_lines.len() >= 512 {
            self.event_debug_lines.pop_front();
        }
        self.event_debug_lines.push_back(line);
    }

    fn ridden_vehicle_definition(&self, vehicle_num: i32) -> Option<jka_assets::vehicle::VehicleDefinition> {
        if vehicle_num <= 0 {
            return None;
        }
        let entity = self
            .presented_entities
            .iter()
            .find(|entity| i32::from(entity.number) == vehicle_num)?;
        let model_index = entity.state.field_i32("modelindex").unwrap_or(0);
        let requested = self.client_game.model_qpath(model_index)?;
        self.player_presenter
            .vehicle_definition_for_model_request(&requested)
            .cloned()
    }

    fn take_event_debug_lines(&mut self) -> Vec<String> {
        self.event_debug_lines.drain(..).collect()
    }

    fn record_event_stat(&mut self, event: EntityEvent, server_time: i32, class: EventDispatchClass) {
        let stat = self.event_stats.entry(event).or_insert(DemoEventStat {
            count: 0,
            handled: 0,
            partial: 0,
            unhandled: 0,
            first_server_time: server_time,
            last_server_time: server_time,
        });
        stat.count = stat.count.saturating_add(1);
        match class {
            EventDispatchClass::Handled => stat.handled = stat.handled.saturating_add(1),
            EventDispatchClass::Partial => stat.partial = stat.partial.saturating_add(1),
            EventDispatchClass::Unhandled => stat.unhandled = stat.unhandled.saturating_add(1),
        }
        stat.last_server_time = server_time;
    }

    /// CG_EntityEvent EV_NOAMMO for the viewer: the follow-up weapon change is
    /// applied by the owner of the local input (see `take_out_of_ammo`).
    fn note_out_of_ammo(&mut self, event: &crate::cgame::PresentationEvent) {
        if event.event != EntityEvent::EV_NOAMMO {
            return;
        }
        let Some(snapshot) = self.client_game.current_snapshot() else { return };
        let ps = &snapshot.player_state;
        let local = ps.field_i32("clientNum").unwrap_or(-1);
        let duel = ps.field_i32("duelInProgress").unwrap_or(0) != 0;
        let duel_index = ps.field_i32("duelIndex").unwrap_or(-1);
        let number = i32::from(event.entity_num);
        if number != local
            || (duel && local != number && duel_index != number)
            || ps.field_i32("m_iVehicleNum").unwrap_or(0) != 0
        {
            return;
        }
        const WP_NONE: i32 = 0;
        const WP_SABER: i32 = 3;
        const WP_NUM_WEAPONS: i32 = 19;
        let weapon = ps.field_i32("weapon").unwrap_or(WP_NONE);
        if weapon == WP_NONE || weapon == WP_SABER {
            return; // vehicle/force-HUD flash cases: no weapon change
        }
        // eventParm < WP_NUM_WEAPONS names the weapon that ran dry (its
        // STAT_WEAPONS bit is dropped) and the change leaves the current one.
        let (old, dry) = match event.parm {
            0 => (0, 0),
            parm if parm < WP_NUM_WEAPONS => (weapon, parm),
            parm => (parm - WP_NUM_WEAPONS, 0),
        };
        if self.pending_out_of_ammo.len() < 8 {
            self.pending_out_of_ammo.push((old, dry));
        }
    }

    /// The text a CG_EntityEvent prints or centre-prints through StringEd:
    /// duel start, item use failures and CTF flag messages.
    fn note_stringed_messages(&mut self, event: &crate::cgame::PresentationEvent) {
        use crate::cgame::CgameNotice;
        use EntityEvent as E;
        let Some(snapshot) = self.client_game.current_snapshot() else { return };
        let local = snapshot.player_state.field_i32("clientNum").unwrap_or(-1);
        let state = &event.state;
        let notice = match event.event {
            E::EV_GLOBAL_DUEL => {
                let involved = ["otherEntityNum", "otherEntityNum2", "groundEntityNum"]
                    .iter()
                    .any(|field| state.field_i32(field) == Some(local));
                involved.then_some(CgameNotice::StringEd {
                    key: "MP_SVGAME_BEGIN_DUEL",
                    player: None,
                    team: None,
                    center: true,
                })
            }
            E::EV_PRIVATE_DUEL if !self.client_game.japro_racemode() => {
                // jaPRO cg_duelSounds: 2 is sound only, 0 disables the start cue.
                let option = self.sound_presenter.as_ref().map_or(1, |sound| sound.game_sounds().duel);
                (i32::from(event.entity_num) == local && event.parm == 2 && matches!(option, 1 | 3))
                    .then_some(CgameNotice::StringEd {
                        key: "MP_SVGAME_BEGIN_DUEL",
                        player: None,
                        team: None,
                        center: true,
                    })
            }
            E::EV_ITEMUSEFAIL if i32::from(event.entity_num) == local => {
                let key = match event.parm {
                    1 => "MP_INGAME_SENTRY_NOROOM",
                    2 => "MP_INGAME_SENTRY_ALREADYPLACED",
                    3 => "MP_INGAME_SHIELD_NOROOM",
                    4 => "MP_INGAME_SEEKER_ALREADYDEPLOYED",
                    _ => return,
                };
                Some(CgameNotice::StringEd { key, player: None, team: None, center: false })
            }
            E::EV_CTFMESSAGE => {
                let key = match event.parm {
                    0 => "MP_INGAME_FRAGGED_FLAG_CARRIER",
                    1 => "MP_INGAME_FLAG_RETURNED",
                    2 => "MP_INGAME_PLAYER_RETURNED_FLAG",
                    3 => "MP_INGAME_PLAYER_CAPTURED_FLAG",
                    4 => "MP_INGAME_PLAYER_GOT_FLAG",
                    _ => return,
                };
                let client = state.field_i32("trickedentindex").unwrap_or(-1);
                let team = state.field_i32("trickedentindex2").unwrap_or(-1);
                let Some(info) = usize::try_from(client)
                    .ok()
                    .filter(|&client| client < 32)
                    .and_then(|client| self.client_game.client_info(client, &self.siege_classes))
                else {
                    return;
                };
                let team = match team {
                    1 => Some("RED"),
                    2 => Some("BLUE"),
                    3 => Some("SPECTATOR"),
                    0 => Some("FREE"),
                    _ => None,
                };
                Some(CgameNotice::StringEd { key, player: Some(info.name), team, center: false })
            }
            _ => None,
        };
        if let Some(notice) = notice {
            self.client_game.push_notice(notice);
        }
    }

    /// TaystJK/jaPRO `cg_killMessage`: EV_OBITUARY is the authoritative kill
    /// event, so this shares exactly the same attacker/target semantics as
    /// `cg_killSounds` and works for live play, demos, and follow views.
    fn note_kill_message(&mut self, event: &crate::cgame::PresentationEvent) {
        use EntityEvent as E;
        if event.event != E::EV_OBITUARY {
            return;
        }
        let option = self
            .sound_presenter
            .as_ref()
            .map_or(1, |sound| sound.game_sounds().kill_message);
        if option == 0 {
            return;
        }
        let Some(snapshot) = self.client_game.current_snapshot() else { return };
        let ps = &snapshot.player_state;
        let local = ps.field_i32("clientNum").unwrap_or(-1);
        let target = event.state.field_i32("otherEntityNum").unwrap_or(-1);
        let attacker = event.state.field_i32("otherEntityNum2").unwrap_or(-1);
        if attacker != local || attacker == target {
            return;
        }
        let Some(info) = usize::try_from(target)
            .ok()
            .filter(|&client| client < 32)
            .and_then(|client| self.client_game.client_info(client, &self.siege_classes))
        else {
            return;
        };
        self.client_game.push_notice(crate::cgame::CgameNotice::KillMessage {
            target: info.name,
            rank: ps.persistant[2],
            score: ps.persistant[0],
            gametype: self.client_game.gametype(),
        });
    }

    /// EV_LOCALTIMER, EV_SCOREPLUM and the saber "no force" flash of EV_NOAMMO.
    fn note_hud_events(&mut self, event: &crate::cgame::PresentationEvent) {
        use EntityEvent as E;
        let Some(snapshot) = self.client_game.current_snapshot() else { return };
        let ps = &snapshot.player_state;
        let local = ps.field_i32("clientNum").unwrap_or(-1);
        match event.event {
            E::EV_LOCALTIMER if event.state.field_i32("owner") == Some(local) => {
                let duration = event.state.field_i32("time2").unwrap_or(0);
                if duration > 0 {
                    self.timer_bar = Some((Instant::now(), duration));
                }
            }
            E::EV_SCOREPLUM if event.state.field_i32("otherEntityNum") == Some(local) => {
                // jaPRO spot icons (eventParm 1) are not drawn.
                if event.parm != 1 {
                    let score = event.state.field_i32("time").unwrap_or(0);
                    self.weapon_fx.add_score_plum(event.position, score);
                }
            }
            E::EV_NOAMMO if i32::from(event.entity_num) == local => {
                if ps.field_i32("weapon") == Some(3) {
                    self.force_flash_until = Some(Instant::now() + Duration::from_millis(1000));
                }
            }
            _ => {}
        }
    }

    /// EV_ITEM_PICKUP / EV_GLOBAL_ITEM_PICKUP for the viewer: HUD icon, "Picked
    /// up" line and weapon auto-select (`CG_ItemPickup`).
    fn note_item_pickup(&mut self, event: &crate::cgame::PresentationEvent) {
        use EntityEvent as E;
        if !matches!(event.event, E::EV_ITEM_PICKUP | E::EV_GLOBAL_ITEM_PICKUP) {
            return;
        }
        let Some(snapshot) = self.client_game.current_snapshot() else { return };
        let ps = &snapshot.player_state;
        if ps.field_i32("duelInProgress").unwrap_or(0) != 0
            || i32::from(event.entity_num) != ps.field_i32("clientNum").unwrap_or(-1)
        {
            return;
        }
        let index = if event.event == E::EV_ITEM_PICKUP {
            // The item entity sits in eventParm; its modelindex is the bg_itemlist index.
            let Ok(item_entity) = u16::try_from(event.parm) else { return };
            if self.item_pickup_until.get(&event.parm).is_some_and(|&until| until >= event.server_time) {
                return; // rww's double-pickup guard
            }
            self.item_pickup_until.insert(event.parm, event.server_time + 500);
            self.client_game
                .entity_state(item_entity)
                .and_then(|state| state.field_i32("modelindex"))
                .unwrap_or(0)
        } else {
            event.parm
        };
        let Some(item) = jka_movement::bg_item(index).filter(|_| index >= 1) else { return };
        if let Some(icon) = jka_movement::bg_item_icon(index) {
            self.item_pickup = Some((icon, Instant::now()));
        }
        const IT_WEAPON: i32 = 1;
        const IT_TEAM: i32 = 8;
        if item.item_type == IT_WEAPON && self.pending_weapon_select.len() < 8 {
            self.pending_weapon_select.push(item.tag);
        }
        if item.item_type != IT_TEAM && !item.classname.is_empty() {
            self.client_game.push_notice(crate::cgame::CgameNotice::ItemPickupLine { classname: item.classname });
        }
    }

    /// The kick after the viewer fires (`CG_FireWeapon`, cg_screenShake 2).
    fn note_weapon_shake(&mut self, event: &crate::cgame::PresentationEvent) {
        use EntityEvent as E;
        if self.screen_shake_level < 2 || !matches!(event.event, E::EV_FIRE_WEAPON | E::EV_ALT_FIRE) {
            return;
        }
        let Some(snapshot) = self.client_game.current_snapshot() else { return };
        if i32::from(event.entity_num) != snapshot.player_state.field_i32("clientNum").unwrap_or(-1) {
            return;
        }
        let alt = event.event == E::EV_ALT_FIRE;
        let weapon = event.state.field_i32("weapon").unwrap_or(0);
        // The charge start time rides in constantLight.
        let charged = ((event.server_time - event.state.field_i32("constantLight").unwrap_or(0)) as f32 * 0.001).clamp(0.2, 3.0) * 2.0;
        let rand = |low: f32, high: f32| low + (high - low) * ((event.receive_sequence % 100) as f32 / 100.0);
        const WP_BRYAR_PISTOL: i32 = 4;
        const WP_BOWCASTER: i32 = 7;
        const WP_REPEATER: i32 = 8;
        const WP_DEMP2: i32 = 9;
        const WP_FLECHETTE: i32 = 10;
        const WP_ROCKET_LAUNCHER: i32 = 11;
        const WP_BRYAR_OLD: i32 = 16;
        let (intensity, ms) = match (weapon, alt) {
            (WP_BRYAR_PISTOL | WP_BRYAR_OLD | WP_DEMP2, true) | (WP_BOWCASTER, false) => (charged, 250),
            (WP_ROCKET_LAUNCHER, _) | (WP_REPEATER, true) | (WP_FLECHETTE, true) => (rand(2.0, 3.0), 350),
            (WP_FLECHETTE, false) => (1.5, 250),
            _ => return,
        };
        self.event_presenter.add_camera_shake(intensity, ms);
    }

    /// EV_FALL / EV_ROLL landings and EV_STEP_* smoothing for the viewer.
    fn note_view_kick(&mut self, event: &crate::cgame::PresentationEvent) {
        use EntityEvent as E;
        let Some(snapshot) = self.client_game.current_snapshot() else { return };
        let ps = &snapshot.player_state;
        let local = ps.field_i32("clientNum").unwrap_or(-1);
        if event.state.field_i32("clientNum").unwrap_or(-2) != local {
            return;
        }
        let time = event.server_time;
        match event.event {
            E::EV_FALL | E::EV_ROLL => {
                // EV_ROLL only runs DoFall for a fall-roll-in-one (eventParm set).
                let falling_to_death = ps.field_i32("fallingToDeath").unwrap_or(0) != 0;
                if !falling_to_death && (event.event == E::EV_FALL || event.parm != 0) {
                    self.event_presenter.view_kick_mut().land(event.parm, time);
                }
            }
            E::EV_STEP_4 | E::EV_STEP_8 | E::EV_STEP_12 | E::EV_STEP_16 => {
                // Demos and followed players interpolate, so they need no smoothing.
                const PMF_FOLLOW: i32 = 4096;
                if (self.live || self.local) && ps.field_i32("pm_flags").unwrap_or(0) & PMF_FOLLOW == 0 {
                    let steps = event.event.as_i32() - E::EV_STEP_4.as_i32() + 1;
                    self.event_presenter.view_kick_mut().step(steps, time);
                }
            }
            _ => {}
        }
    }

    fn dispatch_prepared_event(
        &mut self,
        prepared: event_workers::PreparedPresentationEvent,
        target_server_time: i32,
        debug_events: u8,
    ) {
        let event_workers::PreparedPresentationEvent { event, sound, fx, visual } = prepared;
        // OpenJK EV_DESTROY_WEAPON_MODEL mutates the target Ghoul2 model before
        // this frame's player/body rendering. Event-worker preparation never
        // owns or mutates presenter state; ordered application stays here.
        self.player_presenter.apply_entity_event(&event);
        self.note_out_of_ammo(&event);
        self.note_view_kick(&event);
        self.note_weapon_shake(&event);
        self.note_item_pickup(&event);
        self.note_hud_events(&event);
        self.note_kill_message(&event);
        self.note_stringed_messages(&event);
        let fx_dispatch = self.weapon_fx.entity_event_prepared(&event, &fx);
        let sound_dispatch_started = Instant::now();
        let sound_dispatch = if self.suppress_audio {
            None
        } else {
            match (self.sound_presenter.as_mut(), sound) {
                (Some(presenter), Some(sound)) => presenter.dispatch_prepared(
                    &event,
                    &self.client_game,
                    &self.siege_classes,
                    target_server_time,
                    sound,
                ),
                _ => None,
            }
        };
        self.client_perf.audio_ms += sound_dispatch_started.elapsed().as_secs_f64() * 1000.0;
        let dispatch = sound_dispatch
            .or(fx_dispatch)
            .unwrap_or_else(|| self.event_presenter.dispatch_prepared(&event, visual));
        self.record_event_stat(event.event, event.server_time, dispatch.class());
        if debug_events >= 1 {
            self.push_event_debug_line(event_debug::accepted_line(&event, &dispatch.status()));
        }
        if debug_events >= 3 {
            for line in event_debug::verbose_lines(&event, &self.client_game) {
                self.push_event_debug_line(line);
            }
        }
    }

    fn event_stats_lines(&self) -> Vec<String> {
        if self.event_stats.is_empty() {
            return vec!["^3CG EVENT STATS:^7 no accepted events observed yet".into()];
        }
        let total: u64 = self.event_stats.values().map(|stat| stat.count).sum();
        let mut rows: Vec<_> = self.event_stats.iter().collect();
        rows.sort_by(|(event_a, stat_a), (event_b, stat_b)| {
            stat_b
                .count
                .cmp(&stat_a.count)
                .then_with(|| event_a.cmp(event_b))
        });
        let mut lines = vec![format!(
            "^3CG EVENT STATS:^7 accepted={} unique={} suppressedDuplicate={} suppressedZero={}  H/P/U columns show presentation result",
            total,
            rows.len(),
            self.event_suppressed_duplicate,
            self.event_suppressed_zero,
        )];
        lines.extend(rows.into_iter().map(|(&event, stat)| {
            format!(
                "  {:>5}  {:<28} id={:<3} cat={:<10} H/P/U={}/{}/{} first={} last={}",
                stat.count,
                event_debug::event_name(event),
                event.as_i32(),
                event_debug::event_category(event),
                stat.handled,
                stat.partial,
                stat.unhandled,
                stat.first_server_time,
                stat.last_server_time,
            )
        }));
        lines
    }

    fn clear_event_stats(&mut self) {
        self.event_stats.clear();
        self.event_suppressed_duplicate = 0;
        self.event_suppressed_zero = 0;
    }

    fn read_next_message(&mut self) -> Result<Option<ProtocolSnapshot>, String> {
        let record = match self.reader.next_record() {
            Ok(Some(record)) => record,
            Ok(None) => {
                self.eof = true;
                if !self.seeking_demo {
                    println!(
                        "DEMO EOF: {} messages, {} valid snapshots",
                        self.messages, self.snapshots
                    );
                }
                return Ok(None);
            }
            Err(error) => {
                return Err(format!(
                    "DEMO FRAMING ERROR AFTER MESSAGE {}: {error}",
                    self.messages
                ));
            }
        };

        let message_index = self.messages;
        let sequence = record.sequence;
        let packet = self.decoder.parse_packet(sequence, &record.payload).map_err(|error| {
            format!(
                "DEMO PROTOCOL ERROR: message {message_index} sequence {sequence} byte~{} bit {}: {}",
                error.bit / 8,
                error.bit,
                error
            )
        })?;
        self.messages += 1;

        let mut decoded_snapshot = None;
        for event in &packet.events {
            match event {
                ServerMessageEvent::Nop => {}
                ServerMessageEvent::Gamestate {
                    server_command_sequence,
                    configstrings,
                    baselines,
                    client_number,
                    checksum_feed,
                } => {
                    if !self.seeking_demo {
                        println!(
                            "DEMO svc_gamestate: sequence={} serverCommandSequence={} configstrings={} baselines={} clientNum={} checksumFeed=0x{:08x}",
                            sequence,
                            server_command_sequence,
                            configstrings,
                            baselines,
                            client_number,
                            checksum_feed
                        );
                    }
                    if let Some(map) = self.decoder.map_name() {
                        if self.map_name.as_deref() != Some(map.as_str()) {
                            if !self.seeking_demo { println!("DEMO map: {map}"); }
                        }
                        self.map_name = Some(map);
                    }
                    self.client_game.reset_gamestate(
                        &self.decoder.configstrings,
                        *server_command_sequence,
                    );
                    self.event_presenter.clear();
                    if let Some(sound) = &mut self.sound_presenter { sound.clear(); }
                }
                ServerMessageEvent::ServerCommand(command) => {
                    self.client_game.queue_server_command(command.clone());
                    if !self.seeking_demo {
                        println!(
                            "DEMO svc_serverCommand #{}: {}",
                            command.sequence,
                            String::from_utf8_lossy(&command.text)
                        );
                    }
                }
                ServerMessageEvent::Snapshot {
                    server_time,
                    message_num,
                    delta_num,
                    entities,
                } => {
                    self.snapshots += 1;
                    if !self.seeking_demo && (self.snapshots == 1 || self.snapshots % 60 == 0) {
                        println!(
                            "DEMO svc_snapshot: serverTime={} message={} delta={} entities={} decodedSnapshots={}",
                            server_time,
                            message_num,
                            delta_num,
                            entities,
                            self.snapshots
                        );
                    }
                    decoded_snapshot = self.decoder.latest_snapshot().cloned();
                }
                ServerMessageEvent::SetGame(game) => {
                    if !self.seeking_demo {
                        println!("DEMO svc_setgame: {}", String::from_utf8_lossy(game));
                    }
                }
                ServerMessageEvent::MapChange => { if !self.seeking_demo { println!("DEMO svc_mapchange"); } }
                ServerMessageEvent::Download(_) => { if !self.seeking_demo { println!("DEMO svc_download"); } }
            }
        }

        Ok(decoded_snapshot)
    }

    fn set_playback_rate(&mut self, now: Instant, rate: f64) -> Result<(), String> {
        if !rate.is_finite() || rate < 0.0 || rate > 100.0 {
            return Err("DEMO SPEED MUST BE BETWEEN 0 AND 100 (REVERSE NEEDS CHECKPOINTS)".into());
        }
        let timeline = self
            .timeline
            .as_mut()
            .ok_or_else(|| "DEMO PLAYBACK CLOCK WAS NOT INITIALIZED".to_owned())?;
        timeline.set_rate(now, rate);
        if let Some(sound) = &mut self.sound_presenter { sound.set_rate(rate as f32); }
        Ok(())
    }

    /// Change the UI playback speed without changing pause state. The play/pause
    /// control owns whether time advances; the speed control owns resume speed.
    fn set_playback_speed(&mut self, now: Instant, speed: f64) -> Result<(), String> {
        if !speed.is_finite() || speed <= 0.0 || speed > 100.0 {
            return Err("DEMO SPEED MUST BE GREATER THAN 0 AND AT MOST 100".into());
        }
        let timeline = self
            .timeline
            .as_mut()
            .ok_or_else(|| "DEMO PLAYBACK CLOCK WAS NOT INITIALIZED".to_owned())?;
        if timeline.rate == 0.0 {
            timeline.resume_rate = speed;
        } else {
            timeline.set_rate(now, speed);
            if let Some(sound) = &mut self.sound_presenter { sound.set_rate(speed as f32); }
        }
        Ok(())
    }

    fn toggle_pause(&mut self, now: Instant) -> Result<f64, String> {
        let timeline = self
            .timeline
            .as_mut()
            .ok_or_else(|| "DEMO PLAYBACK CLOCK WAS NOT INITIALIZED".to_owned())?;
        timeline.toggle_pause(now);
        if let Some(sound) = &mut self.sound_presenter { sound.set_rate(timeline.rate as f32); }
        Ok(timeline.rate)
    }

    fn playback_rate(&self) -> Option<f64> {
        self.timeline.map(|timeline| timeline.rate)
    }

    fn set_audio_suppressed(&mut self, suppressed: bool) {
        if self.suppress_audio == suppressed {
            return;
        }
        self.suppress_audio = suppressed;
        // Stop anything already queued/looping at the boundary. On resume the
        // destination frame rebuilds valid loops and future one-shots normally.
        if let Some(sound) = &mut self.sound_presenter {
            sound.clear();
        }
    }

    fn demo_duration_ms(&self) -> Option<i32> {
        self.demo_index.as_ref().map(DemoIndex::duration_ms)
    }

    fn demo_elapsed_ms(&self, now: Instant) -> Option<f64> {
        let first = f64::from(self.demo_index.as_ref()?.first_active_server_time?);
        let current = self.timeline?.target_time_ms(now);
        Some((current - first).clamp(0.0, f64::from(self.demo_duration_ms()?.max(0))))
    }

    fn demo_followed_client(&self) -> Option<i32> {
        self.current_snapshot
            .as_ref()
            .and_then(|snapshot| snapshot.player_state.field_i32("clientNum"))
    }

    fn demo_visible_players(&self) -> Vec<(i32, String)> {
        let authoritative = self.demo_followed_client();
        let mut out = Vec::<(i32, String)>::new();
        for client in authoritative.into_iter().chain(
            self.presented_entities.iter()
                .filter(|entity| entity.entity_type == ET_PLAYER)
                .map(|entity| i32::from(entity.number))
        ) {
            if out.iter().any(|(existing, _)| *existing == client) {
                continue;
            }
            let name = usize::try_from(client).ok()
                .and_then(|client| self.client_game.client_info(client, &self.siege_classes))
                .map(|info| info.name)
                .filter(|name| !name.is_empty())
                .unwrap_or_else(|| format!("CLIENT {client}"));
            out.push((client, name));
        }
        out.sort_by_key(|(client, _)| *client);
        out
    }

    fn demo_fake_view(&self, client_num: i32) -> Option<DemoFakeView> {
        let entity = self.presented_entities.iter().find(|entity| {
            entity.entity_type == ET_PLAYER && i32::from(entity.number) == client_num
        })?;
        // Remote demos do not carry another client's playerState/viewheight, so this
        // is intentionally a presentation approximation. Standing eye height is the
        // JKA player-view default; authoritative POV keeps the exact playerState path.
        let mut eye = entity.origin;
        eye[2] += 26.0;
        Some(DemoFakeView {
            client_num,
            eye_position: scene::render_position(eye),
            view_angles: entity.angles,
        })
    }

    fn demo_area_mask(&self) -> Option<[u8; 32]> {
        self.current_snapshot.as_ref().map(|snapshot| snapshot.area_mask)
    }

    fn reset_demo_stream_for_seek(&mut self) {
        self.reader = DemoReader::new(Cursor::new(self.demo_bytes.clone()));
        self.decoder = ServerMessageDecoder::new();
        self.messages = 0;
        self.snapshots = 0;
        self.phase = SessionPhase::WaitingForMap;
        self.map_name = None;
        self.pending_snapshot = None;
        self.current_snapshot = None;
        self.next_snapshot = None;
        self.first_server_time = None;
        self.timeline = None;
        self.eof = false;
        self.player_position = None;
        self.client_game = ClientGameState::new();
        self.presented_entities.clear();
        self.event_presenter.clear();
        self.reward_active = None;
        self.reward_queue.clear();
        if let Some(sound) = &mut self.sound_presenter {
            sound.clear();
        }
        self.weapon_fx.reset_for_seek(0);
        self.player_presenter.reset_for_seek();
        self.fx_draws.clear();
        self.fx_lights = Arc::new(Vec::new());
        self.fx_blades = Arc::new(Vec::new());
        self.fx_surfaces = Arc::new(Vec::new());
        self.dynamic_models = Arc::new(Vec::new());
        self.inline_models = Arc::new(Vec::new());
        self.clear_event_stats();
    }

    fn seek_demo(&mut self, now: Instant, elapsed_ms: i32) -> Result<DemoCameraSample, String> {
        if self.live {
            return Err("DEMO SEEK IS NOT AVAILABLE FOR LIVE SESSIONS".into());
        }
        self.seeking_demo = true;
        let result = self.seek_demo_inner(now, elapsed_ms);
        self.seeking_demo = false;
        result
    }

    fn seek_demo_inner(&mut self, now: Instant, elapsed_ms: i32) -> Result<DemoCameraSample, String> {
        let (first, duration) = {
            let index = self
                .demo_index
                .as_ref()
                .ok_or_else(|| "DEMO TIMELINE INDEX IS UNAVAILABLE".to_owned())?;
            let first = index
                .first_active_server_time
                .ok_or_else(|| "DEMO TIMELINE HAS NO ACTIVE START".to_owned())?;
            (first, index.duration_ms())
        };
        let elapsed_ms = elapsed_ms.clamp(0, duration);
        let target = first.saturating_add(elapsed_ms);
        let (rate, resume_rate) = self
            .timeline
            .map(|timeline| (timeline.rate, timeline.resume_rate))
            .unwrap_or((1.0, 1.0));

        self.reset_demo_stream_for_seek();
        let _map = self.read_until_map()?;
        let _ = self.begin_after_map_load(now)?;

        while self
            .next_snapshot
            .as_ref()
            .is_some_and(|snapshot| target >= snapshot.server_time)
        {
            self.client_game.transition_snapshot(target)?;
            self.current_snapshot = self.next_snapshot.take();
            self.next_snapshot = self.read_next_snapshot()?;
            self.client_game.set_next_snapshot(self.next_snapshot.as_ref())?;
        }

        // Seeking reconstructs authoritative CGame state, but transient effects
        // from the replay-to-target pass must not burst onto the destination frame.
        let _ = self.client_game.drain_presentation_events();
        let _ = self.client_game.drain_event_check_traces();
        // Replayed server commands are historical at the seek destination. The App
        // reconstructs chat/centerprint explicitly from the indexed demo timeline.
        let _ = self.client_game.drain_notices();
        self.event_presenter.clear();
        if let Some(sound) = &mut self.sound_presenter {
            sound.clear();
            sound.set_rate(rate as f32);
        }
        self.weapon_fx.reset_for_seek(target);
        self.weapon_fx.begin_frame(target);
        self.presented_entities = self.client_game.present_entities_at(f64::from(target))?;
        let sample = self
            .sample_at(f64::from(target), target, true)
            .ok_or_else(|| "DEMO SEEK TARGET HAS NO CAMERA PLAYERSTATE".to_owned())?;
        self.player_position = Some(glam::Vec3::from_array(sample.player_position));
        if let Some(timeline) = &mut self.timeline {
            timeline.seek(now, f64::from(target));
            timeline.rate = rate;
            timeline.resume_rate = resume_rate;
        }
        Ok(sample)
    }

    fn read_until_map(&mut self) -> Result<String, String> {
        loop {
            // A normal JKA gamestate packet ends before the first snapshot, but
            // preserve a snapshot if a compatible producer places both in one
            // server message. The shared decoder has already consumed the whole
            // packet, so dropping that snapshot here would move playback's first
            // visible frame forward by one message.
            if let Some(snapshot) = self.read_next_message()? {
                if self.pending_snapshot.is_none() {
                    self.pending_snapshot = Some(snapshot);
                }
            }
            if let Some(map) = self.map_name.clone().or_else(|| self.decoder.map_name()) {
                self.map_name = Some(map.clone());
                return Ok(map);
            }
            if self.eof {
                return Err(format!("DEMO REACHED EOF BEFORE GAMESTATE MAP: {}", self.qpath));
            }
        }
    }

    /// CG_ReadNextSnapshot: every snapshot cgame reads is logged for the lagometer.
    fn read_next_snapshot(&mut self) -> Result<Option<ProtocolSnapshot>, String> {
        let snapshot = self.read_next_snapshot_unlogged()?;
        if let Some(snapshot) = &snapshot {
            // Demos carry no ping: cgame derives one from the serverinfo's sv_fps.
            let demo = !self.live;
            let svfps = if demo { self.client_game.server_fps() } else { 20 };
            self.lagometer.add_snapshot_info(
                &crate::lagometer::SnapshotInfo {
                    message_num: snapshot.message_num,
                    server_time: snapshot.server_time,
                    command_time: snapshot.player_state.field_i32("commandTime").unwrap_or(0),
                    ping: snapshot.ping,
                    flags: snapshot.snap_flags,
                },
                demo,
                svfps,
            );
        }
        Ok(snapshot)
    }

    fn read_next_snapshot_unlogged(&mut self) -> Result<Option<ProtocolSnapshot>, String> {
        if self.live {
            // CG_ReadNextSnapshot: nothing new yet simply means extrapolate.
            return Ok(self.live_snapshots.pop_front());
        }
        loop {
            if self.eof {
                return Ok(None);
            }
            if let Some(snapshot) = self.read_next_message()? {
                return Ok(Some(snapshot));
            }
        }
    }

    fn begin_after_map_load(&mut self, now: Instant) -> Result<DemoCameraSample, String> {
        const SNAPFLAG_NOT_ACTIVE: u8 = 1 << 1;

        // CL_FirstSnapshot ignores connection/zombie snapshots carrying
        // SNAPFLAG_NOT_ACTIVE. Do the same before establishing our playback time
        // base so the first visible frame is an actually active game snapshot.
        let first = loop {
            let candidate = if let Some(snapshot) = self.pending_snapshot.take() {
                Some(snapshot)
            } else {
                self.read_next_snapshot()?
            };
            let snapshot = candidate
                .ok_or_else(|| format!("DEMO HAS NO ACTIVE SNAPSHOT: {}", self.qpath))?;
            if snapshot.snap_flags & SNAPFLAG_NOT_ACTIVE == 0 {
                break snapshot;
            }
        };
        self.first_server_time = Some(first.server_time);
        self.client_game.set_initial_snapshot(&first)?;
        self.current_snapshot = Some(first);
        self.next_snapshot = self.read_next_snapshot()?;
        self.client_game.set_next_snapshot(self.next_snapshot.as_ref())?;
        self.timeline = Some(DemoTimeline::new(self.first_server_time.unwrap(), now));
        self.phase = SessionPhase::Playing;
        self.sample_at(
            f64::from(self.first_server_time.unwrap()),
            self.first_server_time.unwrap(),
            false,
        )
            .ok_or_else(|| "DEMO FIRST SNAPSHOT HAS NO CAMERA PLAYERSTATE".to_owned())
    }

    /// Live CG_Init/CG_ProcessSnapshots start: begin from the newest active
    /// snapshot received while the map loaded. Returns false until one exists.
    fn begin_live(&mut self) -> Result<bool, String> {
        const SNAPFLAG_NOT_ACTIVE: u8 = 1 << 1;
        let Some(index) = self
            .live_snapshots
            .iter()
            .rposition(|snapshot| snapshot.snap_flags & SNAPFLAG_NOT_ACTIVE == 0)
        else {
            // Inactive snapshots only mean the server has not entered us yet.
            let keep_from = self.live_snapshots.len().saturating_sub(1);
            self.live_snapshots.drain(..keep_from);
            return Ok(false);
        };
        self.live_snapshots.drain(..index);
        let first = self.live_snapshots.pop_front().expect("indexed above");
        self.first_server_time = Some(first.server_time);
        self.client_game.set_initial_snapshot(&first)?;
        self.current_snapshot = Some(first);
        self.next_snapshot = self.read_next_snapshot()?;
        self.client_game.set_next_snapshot(self.next_snapshot.as_ref())?;
        self.phase = SessionPhase::Playing;
        Ok(true)
    }

    fn advance(
        &mut self,
        now: Instant,
        third_person: ThirdPersonSettings,
        first_person_lightsaber: bool,
        debug_events: u8,
        event_workers_enabled: bool,
        ghoul2_view: Option<Ghoul2PresentationView>,
        rt_rigid_casters_enabled: bool,
        blob_shadows_enabled: bool,
    ) -> Result<(DemoAdvance, DemoCameraSample), String> {
        if self.phase != SessionPhase::Playing {
            return Err("DEMO PLAYBACK ADVANCED BEFORE MAP LOAD".to_owned());
        }
        let presentation_time_ms = self
            .timeline
            .ok_or_else(|| "DEMO PLAYBACK CLOCK WAS NOT INITIALIZED".to_owned())?
            .target_time_ms(now);
        let target_server_time = presentation_time_ms.floor() as i32;
        self.advance_to_with_prediction(
            target_server_time,
            presentation_time_ms,
            third_person,
            first_person_lightsaber,
            debug_events,
            event_workers_enabled,
            ghoul2_view,
            rt_rigid_casters_enabled,
            blob_shadows_enabled,
            false,
            None,
        )
    }

    fn advance_to(
        &mut self,
        target_server_time: i32,
        third_person: ThirdPersonSettings,
        first_person_lightsaber: bool,
        debug_events: u8,
        event_workers_enabled: bool,
        ghoul2_view: Option<Ghoul2PresentationView>,
        rt_rigid_casters_enabled: bool,
        blob_shadows_enabled: bool,
    ) -> Result<(DemoAdvance, DemoCameraSample), String> {
        self.advance_to_with_prediction(
            target_server_time,
            f64::from(target_server_time),
            third_person,
            first_person_lightsaber,
            debug_events,
            event_workers_enabled,
            ghoul2_view,
            rt_rigid_casters_enabled,
            blob_shadows_enabled,
            false,
            None,
        )
    }

    /// `predict` is CG_PredictPlayerState: given this frame's snap/nextSnap it
    /// returns cg.predictedPlayerState plus the decaying view error.
    fn advance_to_with_prediction(
        &mut self,
        target_server_time: i32,
        presentation_time_ms: f64,
        third_person: ThirdPersonSettings,
        first_person_lightsaber: bool,
        debug_events: u8,
        event_workers_enabled: bool,
        ghoul2_view: Option<Ghoul2PresentationView>,
        rt_rigid_casters_enabled: bool,
        blob_shadows_enabled: bool,
        no_predict: bool,
        predict: Option<&mut dyn FnMut(&ProtocolSnapshot, Option<&ProtocolSnapshot>, &[PresentedEntity]) -> Result<Option<LivePredictionFrame>, String>>,
    ) -> Result<(DemoAdvance, DemoCameraSample), String> {
        self.client_perf = ClientFramePerf::default();
        self.player_presenter.begin_perf_frame();
        self.player_presenter
            .set_rt_shadow_casters_enabled(rt_rigid_casters_enabled);
        self.player_presenter.begin_blob_shadow_frame(blob_shadows_enabled);
        self.client_perf.ghoul2_skinning_mode = self.player_presenter.skinning_mode();
        let snapshot_started = Instant::now();
        let current_time = self
            .current_snapshot
            .as_ref()
            .map(|snapshot| snapshot.server_time)
            .ok_or_else(|| "DEMO HAS NO CURRENT SNAPSHOT".to_owned())?;
        // Live cl.serverTime can trail the newest snapshot right after the
        // first one or a time reset; CG_ProcessSnapshots simply holds there.
        let target_server_time = if self.live { target_server_time.max(current_time) } else { target_server_time };
        let presentation_time_ms = if self.live {
            presentation_time_ms.max(f64::from(current_time))
        } else {
            presentation_time_ms
        };
        if target_server_time < current_time {
            return Err(format!(
                "DEMO REVERSE/SEEK REQUIRES CHECKPOINT RESTORE: target {target_server_time} < current snapshot {current_time}"
            ));
        }

        if let (Some(current), Some(next)) = (&self.current_snapshot, &self.next_snapshot) {
            if next.server_time < current.server_time {
                return Err(format!(
                    "DEMO SERVER TIME WENT BACKWARDS: message {} time {} after message {} time {}",
                    next.message_num, next.server_time, current.message_num, current.server_time
                ));
            }
        }

        // CG_ProcessSnapshots: with no nextSnap, try to read one before
        // deciding to extrapolate. Live snapshots arrive between frames.
        if self.next_snapshot.is_none() {
            self.next_snapshot = self.read_next_snapshot()?;
            if self.next_snapshot.is_some() {
                self.client_game.set_next_snapshot(self.next_snapshot.as_ref())?;
            }
        }

        let mut camera_teleported = false;
        while self
            .next_snapshot
            .as_ref()
            .is_some_and(|snapshot| target_server_time >= snapshot.server_time)
        {
            if let (Some(current), Some(next)) = (&self.current_snapshot, &self.next_snapshot) {
                camera_teleported |= snapshot_discontinuity(current, next);
                // TaystJK CG_TransitionSnapshot: when client-side movement
                // prediction does not own the presented playerState, committed
                // snapshots must drive CG_TransitionPlayerState themselves.
                // PMF_FOLLOW is especially important here: Predictor::predict
                // intentionally returns no predicted state while spectating a
                // player, so otherwise their predictable EV_JUMP / EV_FALL /
                // step events never reach the shared event/audio path.
                if snapshot_owns_playerstate_events(
                    self.live,
                    self.local,
                    no_predict,
                    self.client_game.synchronous_clients(),
                    &next.player_state,
                ) {
                    self.client_game.transition_predicted_player_state(
                        &next.player_state,
                        &current.player_state,
                        next.server_time,
                    )?;
                }
            }
            self.client_game.transition_snapshot(target_server_time)?;
            self.current_snapshot = self.next_snapshot.take();
            self.next_snapshot = self.read_next_snapshot()?;
            self.client_game.set_next_snapshot(self.next_snapshot.as_ref())?;
        }

        // CG_ExecuteNewServerCommands runs before entity presentation. In
        // OpenJK, reliable ircg/rcg commands mutate Ghoul2 instances before
        // CG_AddPacketEntities sees the corresponding body/respawn state.
        for command in self.client_game.drain_ghoul2_commands() {
            self.player_presenter.apply_ghoul2_server_command(command);
        }

        // FX_AdjustTime: effects spawned by this frame's events and entities
        // start at cg.time.
        self.weapon_fx.begin_frame(target_server_time);
        self.presented_entities = self.client_game.present_entities_at(presentation_time_ms)?;
        let predicted = match (predict, self.current_snapshot.as_ref()) {
            (Some(predict), Some(current)) => predict(current, self.next_snapshot.as_ref(), &self.presented_entities)?,
            _ => None,
        };
        if let Some(prediction) = &predicted {
            // CG_TransitionPlayerState / CG_CheckPlayerstateEvents on the state
            // being presented, so events land on the frame they are drawn.
            self.client_game.transition_predicted_player_state(
                &prediction.display,
                &prediction.previous_display,
                target_server_time,
            )?;
        }
        let sample = match &predicted {
            Some(prediction) => sample_player_state(
                &prediction.display,
                target_server_time,
                camera_teleported,
                prediction.error,
            ),
            None => self.sample_at(presentation_time_ms, target_server_time, camera_teleported),
        }
        .ok_or_else(|| "DEMO CURRENT SNAPSHOT HAS NO CAMERA PLAYERSTATE".to_owned())?;
        self.client_perf.snapshot_ms = snapshot_started.elapsed().as_secs_f64() * 1000.0;

        // CG_AddEntities adds cg.predictedPlayerEntity separately from packet
        // entities. Audio has the same ownership rule: the local/followed
        // player's loops and entity position must still exist even though
        // present_entities() intentionally skips that packet entity.
        let followed_entity = match &predicted {
            Some(prediction) => crate::cgame::presented_player_state_entity(&prediction.display),
            None => self.client_game.present_followed_player_at(presentation_time_ms),
        };
        self.audio_followed_entity.clone_from(&followed_entity);

        // Presentation needs a renderer view before App::apply_demo_camera runs.
        // First person can use this frame's exact sampled eye immediately. Third
        // person needs collision/orbit state owned by App, so it uses the previous
        // rendered third-person camera as a one-frame hint. Never reuse that hint
        // across a teleport/snapshot discontinuity.
        let ghoul2_view = if sample.teleported {
            None
        } else if !rendering_third_person(third_person, first_person_lightsaber, sample.policy) {
            ghoul2_view.map(|view| {
                let yaw = sample.view_angles[1].to_radians();
                let pitch = -sample.view_angles[0].to_radians();
                let (sy, cy) = yaw.sin_cos();
                let (sp, cp) = pitch.sin_cos();
                view.with_pose(sample.eye_position, [cy * cp, sp, -sy * cp])
            })
        } else {
            ghoul2_view
        };
        let audio_started = Instant::now();
        if !self.suppress_audio {
            if let Some(sound) = &mut self.sound_presenter {
                sound.update_loops(
                    &self.client_game,
                    &self.siege_classes,
                    &self.presented_entities,
                    followed_entity.as_ref(),
                    sample.client_num as u16,
                    scene::jka_position(sample.eye_position),
                    target_server_time,
                );
                let yaw = sample.view_angles[1].to_radians();
                sound.frame(
                    crate::audio::Listener {
                        entity: sample.client_num as u16,
                        origin: scene::jka_position(sample.eye_position),
                        ahead: [yaw.cos(), yaw.sin(), 0.0],
                        up: [0.0, 0.0, 1.0],
                        left: [-yaw.sin(), yaw.cos(), 0.0],
                    },
                    &self.presented_entities,
                    followed_entity.as_ref(),
                );
            }
        }
        self.client_perf.audio_ms += audio_started.elapsed().as_secs_f64() * 1000.0;

        let events_started = Instant::now();
        // OpenJK's cg_debugEvents only prints accepted CG_EntityEvent cases.
        // Keep level 1 similarly compact; level 2 additionally explains why
        // candidate events were suppressed by CG_CheckEvents.
        let traces = self.client_game.drain_event_check_traces();
        for trace in &traces {
            match trace.disposition {
                EventCheckDisposition::Duplicate => {
                    self.event_suppressed_duplicate =
                        self.event_suppressed_duplicate.saturating_add(1);
                }
                EventCheckDisposition::Zero => {
                    self.event_suppressed_zero = self.event_suppressed_zero.saturating_add(1);
                }
                EventCheckDisposition::Accepted | EventCheckDisposition::NoEvent => {}
            }
        }
        if debug_events >= 2 {
            for trace in &traces {
                if let Some(line) = event_debug::trace_line(trace) {
                    self.push_event_debug_line(line);
                }
            }
        }

        let event_count = self.client_game.presentation_event_count();
        if event_workers_enabled && event_count > 1 {
            let queued_events = self.client_game.drain_presentation_events();
            let sound_prep = self
                .sound_presenter
                .as_ref()
                .map(crate::cgame::sound_presenter::SoundPresenter::prep_data);
            let fx_saber_definitions = self.weapon_fx.saber_definitions();
            let prepared_batch = event_workers::prepare_batch(
                queued_events,
                &self.client_game,
                &self.siege_classes,
                sound_prep,
                fx_saber_definitions,
                true,
            );
            self.client_perf.event_prepare_ms = prepared_batch.stats.wall_ms;
            self.client_perf.event_worker_jobs = prepared_batch.stats.jobs;
            self.client_perf.event_worker_threads = prepared_batch.stats.pool_threads;
            self.client_perf.event_worker_parallel = prepared_batch.stats.parallel;

            let prepared_events = prepared_batch.events;
            if !self.suppress_audio {
                if let Some(sound_presenter) = self.sound_presenter.as_mut() {
                    let decode_jobs = sound_presenter.stage_prepared_asset_decodes(
                        prepared_events
                            .iter()
                            .filter(|prepared| {
                                target_server_time.saturating_sub(prepared.event.server_time) <= 250
                            })
                            .filter_map(|prepared| prepared.sound.as_ref()),
                        &self.client_game,
                        &self.siege_classes,
                    );
                    let decoded = event_workers::decode_sound_batch(decode_jobs, true);
                    self.client_perf.event_sound_decode_ms = decoded.stats.wall_ms;
                    self.client_perf.event_sound_decode_jobs = decoded.stats.jobs;
                    self.client_perf.event_sound_decode_parallel = decoded.stats.parallel;
                    sound_presenter.queue_predecoded_assets(decoded.results);
                } else {
                    self.client_perf.event_sound_decode_ms = 0.0;
                    self.client_perf.event_sound_decode_jobs = 0;
                    self.client_perf.event_sound_decode_parallel = false;
                }
            } else {
                self.client_perf.event_sound_decode_ms = 0.0;
                self.client_perf.event_sound_decode_jobs = 0;
                self.client_perf.event_sound_decode_parallel = false;
            }

            for prepared in prepared_events {
                self.dispatch_prepared_event(prepared, target_server_time, debug_events);
            }
        } else {
            // Exact single-thread baseline: no temporary batch allocation. The
            // same pure preparation functions run inline, then side effects are
            // applied immediately in receive-queue order.
            let mut prep_ms = 0.0;
            let mut jobs = 0u32;
            while let Some(event) = self.client_game.pop_presentation_event() {
                let sound_prep = self
                    .sound_presenter
                    .as_ref()
                    .map(crate::cgame::sound_presenter::SoundPresenter::prep_data);
                let fx_saber_definitions = self.weapon_fx.saber_definitions();
                let prep_started = Instant::now();
                let prepared = event_workers::prepare_inline(
                    event,
                    &self.client_game,
                    &self.siege_classes,
                    sound_prep,
                    fx_saber_definitions,
                );
                prep_ms += prep_started.elapsed().as_secs_f64() * 1000.0;
                jobs = jobs.saturating_add(1);
                self.dispatch_prepared_event(prepared, target_server_time, debug_events);
            }
            self.client_perf.event_prepare_ms = prep_ms;
            self.client_perf.event_worker_jobs = jobs;
            self.client_perf.event_worker_threads = 0;
            self.client_perf.event_worker_parallel = false;
            self.client_perf.event_sound_decode_ms = 0.0;
            self.client_perf.event_sound_decode_jobs = 0;
            self.client_perf.event_sound_decode_parallel = false;
        }
        if !self.logged_entity_summary {
            let summary = self.client_game.summarize_entities();
            println!(
                "DEMO ENTITY TYPES: total={} players={} npcs={} movers={} missiles={} items={} eventEntities={} other={}",
                summary.total,
                summary.players,
                summary.npcs,
                summary.movers,
                summary.missiles,
                summary.items,
                summary.event_entities,
                summary.other,
            );
            println!(
                "DEMO GAME RULES: gametype={} weaponDisable=0x{:08x}",
                self.client_game.gametype(),
                self.client_game.weapon_disable_mask() as u32,
            );
            for entity in self
                .presented_entities
                .iter()
                .filter(|entity| entity.entity_type == crate::cgame::ET_PLAYER)
            {
                let client_num = entity
                    .state
                    .field_i32("clientNum")
                    .unwrap_or(i32::from(entity.number));
                if client_num < 0 {
                    continue;
                }
                match self
                    .client_game
                    .client_info(client_num as usize, &self.siege_classes)
                {
                    Some(info) => println!(
                        "  ET_PLAYER entity={} clientNum={} name={:?} model={}/{} glm={} skin={} siegeclass={:?}",
                        entity.number,
                        client_num,
                        info.name,
                        info.model_name,
                        info.skin_name,
                        info.model_qpath(),
                        info.skin_qpath(),
                        info.siege_class,
                    ),
                    None => println!(
                        "  ET_PLAYER entity={} clientNum={} has no CS_PLAYERS configstring",
                        entity.number, client_num
                    ),
                }
            }
            self.logged_entity_summary = true;
        }
        self.client_perf.events_ms = events_started.elapsed().as_secs_f64() * 1000.0;

        self.player_position = Some(glam::Vec3::from_array(sample.player_position));
        self.update_race_timer(target_server_time, predicted.as_ref().map(|prediction| &prediction.display));
        // CG_AddLagometerFrameInfo: cg.time - cg.latestSnapshotTime, where the latest
        // snapshot is the newest one received, not just the newest one read.
        let latest_snapshot_time = self
            .live_snapshots
            .back()
            .map(|snapshot| snapshot.server_time)
            .or_else(|| self.next_snapshot.as_ref().map(|snapshot| snapshot.server_time))
            .or_else(|| self.current_snapshot.as_ref().map(|snapshot| snapshot.server_time))
            .unwrap_or(target_server_time);
        self.lagometer.add_frame_info(target_server_time, latest_snapshot_time);
        self.vote_ui = crate::vote::read(
            |index| self.client_game.configstring(index).map(crate::cgame::bytes_to_lossless_ascii),
            target_server_time,
        );

        // CG_AddEntities adds cg.predictedPlayerEntity for the local player.
        let followed_entity = match &predicted {
            Some(prediction) => crate::cgame::presented_player_state_entity(&prediction.display),
            None => self.client_game.present_followed_player_at(presentation_time_ms),
        };
        let followed_entity_num = followed_entity.as_ref().map(|entity| entity.number);
        // forceGripCripple is one of the few exact victim-side grip signals in
        // vanilla playerState. Remote entityState does not transmit
        // forceGripEntityNum, so PlayerPresenter reconstructs those targets
        // from each active gripper's view trace.
        let local_force_gripped = predicted
            .as_ref()
            .map(|prediction| prediction.display.field_i32("fd.forceGripCripple").unwrap_or(0) != 0)
            .or_else(|| {
                self.current_snapshot.as_ref().map(|snapshot| {
                    snapshot.player_state.field_i32("fd.forceGripCripple").unwrap_or(0) != 0
                })
            })
            .unwrap_or(false);
        self.player_presenter.prepare_force_grip_targets(
            &self.presented_entities,
            followed_entity.as_ref(),
            local_force_gripped,
            target_server_time,
        );
        // PMF_TIME_KNOCKBACK is available only for the local/followed
        // playerState. Remote victims are confirmed from event-correlated
        // entity trajectory changes inside PlayerPresenter.
        const PMF_TIME_KNOCKBACK: i32 = 64;
        let local_knockback = predicted
            .as_ref()
            .map(|prediction| prediction.display.field_i32("pm_flags").unwrap_or(0) & PMF_TIME_KNOCKBACK != 0)
            .or_else(|| {
                self.current_snapshot.as_ref().map(|snapshot| {
                    snapshot.player_state.field_i32("pm_flags").unwrap_or(0) & PMF_TIME_KNOCKBACK != 0
                })
            })
            .unwrap_or(false);
        self.player_presenter.prepare_impulse_ragdolls(
            &self.presented_entities,
            followed_entity.as_ref(),
            local_knockback,
            target_server_time,
        );

        // Broadsword historically advanced ragdoll state immediately before
        // Ghoul2 submission. Keep the same presentation ownership: Rapier is
        // stepped once here, while OpenJK snapshot/pmove state stays untouched.
        self.player_presenter.begin_physics_frame(target_server_time);

        let entity_present_started = Instant::now();
        let (mut dynamic_models, inline_models, dispatch_summary) = self
            .entity_presenter
            .present_snapshot_entities(
                &self.presented_entities,
                &self.client_game,
                target_server_time,
                &mut self.player_presenter,
                &mut self.weapon_fx,
                rt_rigid_casters_enabled,
            );
        self.client_perf.entity_present_ms = entity_present_started.elapsed().as_secs_f64() * 1000.0;
        self.inline_models = Arc::new(inline_models);
        if !self.logged_dispatch_summary {
            println!(
                "DEMO ENTITY DISPATCH: general={} movers={} items={} missiles={} npcs={} fx={} other={} renderedSurfaces={}",
                dispatch_summary.general,
                dispatch_summary.movers,
                dispatch_summary.items,
                dispatch_summary.missiles,
                dispatch_summary.npcs,
                dispatch_summary.fx,
                dispatch_summary.other,
                dispatch_summary.rendered_surfaces,
            );
            self.logged_dispatch_summary = true;
        }
        let player_present_started = Instant::now();
        dynamic_models.extend(self.player_presenter.present_snapshot_players(
            &self.presented_entities,
            &self.client_game,
            &self.siege_classes,
            target_server_time,
            followed_entity_num,
            self.demo_hidden_view_client.and_then(|client| u16::try_from(client).ok()),
            ghoul2_view,
            self.forced_player_models.as_ref(),
        ));
        self.client_perf.player_present_ms = player_present_started.elapsed().as_secs_f64() * 1000.0;
        // OpenJK always runs CG_Player for the local/predicted player. In first
        // person it marks the refEntity RF_THIRD_PERSON so the body is not
        // submitted to the main view, but its animation/Ghoul2 state continues
        // to advance. Mirror that ownership here instead of recreating the local
        // player only when cg_thirdPerson is enabled.
        let render_followed_body =
            rendering_third_person(third_person, first_person_lightsaber, sample.policy);
        let followed_started = Instant::now();
        if let Some(entity) = followed_entity {
            let client_num = entity.state.field_i32("clientNum").unwrap_or(sample.client_num);
            if client_num >= 0 {
                if let Some(info) = self.client_game.client_info(client_num as usize, &self.siege_classes) {
                    let look_target_origin = if entity.state.field_i32("hasLookTarget").unwrap_or(0) != 0 {
                        let look_target = entity.state.field_i32("lookTarget").unwrap_or(-1);
                        self.presented_entities
                            .iter()
                            .find(|candidate| i32::from(candidate.number) == look_target)
                            .map(|candidate| candidate.origin)
                    } else {
                        None
                    };
                    self.player_presenter.queue_player_sprites(
                        &entity,
                        &self.client_game,
                        target_server_time,
                        render_followed_body,
                    );
                    dynamic_models.extend(self.player_presenter.present_player_entity(
                        &entity,
                        &info,
                        target_server_time,
                        local_player_alpha(third_person.alpha),
                        look_target_origin,
                        sample.teleported,
                        render_followed_body,
                        // Without a view the presenter cannot pick a Ghoul2 LOD,
                        // so the local player's own model would stay at LOD 0.
                        ghoul2_view,
                    )?);
                    // Snapshot players already submit their thrown sabers in
                    // present_snapshot_players. The local/followed player can
                    // instead be synthesized from playerState (and therefore
                    // absent from the packet-entity list), so mirror OpenJK's
                    // CG_Player saberEntityNum path here only for that case.
                    if !self
                        .presented_entities
                        .iter()
                        .any(|candidate| candidate.number == entity.number)
                    {
                        dynamic_models.extend(self.player_presenter.present_thrown_saber_for_player(
                            &entity,
                            &info,
                            &self.presented_entities,
                            &self.client_game,
                            target_server_time,
                            local_player_alpha(third_person.alpha),
                        )?);
                    }
                }
            }
        }
        self.client_perf.followed_player_ms = followed_started.elapsed().as_secs_f64() * 1000.0;
        let cosmetics = self.player_presenter.drain_cosmetic_draws();
        if !cosmetics.is_empty() {
            dynamic_models.extend(self.entity_presenter.present_cosmetics(cosmetics));
        }
        // CG_DrawMiscStaticModels: client-placed map props, culled to the view.
        dynamic_models.extend(self.entity_presenter.present_static_models(ghoul2_view));
        if let Some(blob_shadows) = self.player_presenter.finish_blob_shadow_frame() {
            dynamic_models.push(blob_shadows);
        }
        let fx_started = Instant::now();
        dynamic_models.extend(self.event_presenter.present(target_server_time));
        self.view_offset_z = self
            .event_presenter
            .view_kick()
            .offset(target_server_time, !render_followed_body);
        self.dynamic_models = Arc::new(dynamic_models);
        // Force-power visuals CG_Player queued for this frame.
        for request in self.player_presenter.drain_fx_requests() {
            self.weapon_fx.player_fx(&request);
        }
        // CG_PlayerFootsteps: the sound, dust and print of each footfall the
        // animations found. The local solo player's snow belongs to Snowflow.
        let stages = self.player_presenter.footstep_stages();
        for impact in self.player_presenter.drain_footsteps() {
            if stages.sounds && !self.suppress_audio {
                if let Some(sound) = &mut self.sound_presenter {
                    let variant = crate::cgame::footsteps::sound_variant(&impact, target_server_time);
                    let step = crate::cgame::footsteps::material_step(impact.material);
                    sound.play_footstep(&step.sound.path(impact.foot.heavy(), variant), impact.entity, impact.position);
                }
            }
            self.weapon_fx.footstep(&impact, stages, self.local && impact.entity < 32);
        }
        // FX_AddScheduledEffects + FX_Add after every CGame submission.
        let fx_frame = self.weapon_fx.end_frame();
        if self.screen_shake_level >= 1 {
            let view = scene::jka_position(sample.eye_position);
            for shake in &fx_frame.shakes {
                self.event_presenter
                    .do_camera_shake(view, shake.origin, shake.intensity, shake.radius, shake.time_ms);
            }
        }
        self.fx_draws = fx_frame.draws;
        self.fx_blades = Arc::new(
            fx_frame
                .blades
                .iter()
                .map(|blade| crate::renderer::CloudForegroundBlade {
                    start: scene::render_position(blade.start),
                    end: scene::render_position(blade.end),
                    radius: blade.radius,
                })
                .collect(),
        );
        self.fx_lights = Arc::new(
            fx_frame
                .lights
                .iter()
                .filter(|light| {
                    light.radius.is_finite()
                        && light.radius > 0.0
                        && light.origin.iter().all(|value| value.is_finite())
                        && light.rgb.iter().all(|value| value.is_finite())
                })
                .map(|light| TransientLight {
                    kind: light.kind,
                    position: scene::render_position(light.origin),
                    color: light.rgb.map(|value| value.max(0.0)),
                    radius: light.radius,
                    // OpenJK's FX primitive passes RGB plus radius to
                    // RE_AddLightToScene; the renderer's point-light intensity
                    // scale of 1.0 is the matching neutral source strength.
                    intensity: 1.0,
                    segment: light.segment.map(|ends| ends.map(scene::render_position)),
                    blade_segments: light.blade_segments.as_ref().map(|blades| blades.iter().map(|blade| {
                        crate::fx::system::FxLightSegment {
                            endpoints: blade.endpoints.map(scene::render_position),
                            ..*blade
                        }
                    }).collect::<Vec<_>>().into()),
                })
                .collect(),
        );
        if !self.suppress_audio {
            if let Some(sound) = &mut self.sound_presenter {
                for fx_sound in &fx_frame.sounds {
                    sound.play_fx_sound(&fx_sound.qpath, fx_sound.origin);
                }
            }
        }
        self.client_perf.fx_ms = fx_started.elapsed().as_secs_f64() * 1000.0;
        let ghoul2 = self.player_presenter.perf_stats();
        self.client_perf.ghoul2_pose_ms = ghoul2.pose_ms;
        self.client_perf.ghoul2_motion_pose_ms = ghoul2.motion_pose_ms;
        self.client_perf.ghoul2_skin_ms = ghoul2.skin_ms;
        self.client_perf.ghoul2_bolt_ms = ghoul2.bolt_ms;
        self.client_perf.ghoul2_pose_evals = ghoul2.pose_evals;
        self.client_perf.ghoul2_motion_pose_evals = ghoul2.motion_pose_evals;
        self.client_perf.ghoul2_bolt_queries = ghoul2.bolt_queries;
        self.client_perf.ghoul2_surfaces = ghoul2.surfaces_skinned;
        self.client_perf.ghoul2_vertices = ghoul2.vertices_skinned;
        self.client_perf.ghoul2_frustum_tests = ghoul2.frustum_tests;
        self.client_perf.ghoul2_frustum_culled = ghoul2.frustum_culled;
        self.client_perf.ghoul2_lod_counts = ghoul2.lod_counts;
        self.client_perf.dynamic_surfaces = u32::try_from(self.dynamic_models.len()).unwrap_or(u32::MAX);
        self.client_perf.dynamic_vertices = self
            .dynamic_models
            .iter()
            .map(|surface| surface.vertex_count() as u64)
            .sum();
        self.client_perf.dynamic_indices = self
            .dynamic_models
            .iter()
            .map(|surface| surface.index_count() as u64)
            .sum();

        let completed = self.eof
            && self.next_snapshot.is_none()
            && self
                .current_snapshot
                .as_ref()
                .is_some_and(|snapshot| target_server_time >= snapshot.server_time);
        Ok((
            if completed {
                DemoAdvance::Completed
            } else {
                DemoAdvance::Running
            },
            sample,
        ))
    }

    fn sample_at(
        &self,
        presentation_time_ms: f64,
        server_time: i32,
        teleported: bool,
    ) -> Option<DemoCameraSample> {
        let current = self.current_snapshot.as_ref()?;
        let next = self.next_snapshot.as_ref();
        // Match CG_SetNextSnap's demo interpolation guards: abrupt teleports,
        // follow-target changes, and map_restart server-count toggles must not
        // blend the recorded camera through space.
        let interpolation_discontinuity =
            next.is_some_and(|next| snapshot_discontinuity(current, next));
        let alpha = if interpolation_discontinuity {
            0.0
        } else {
            next.filter(|next| next.server_time > current.server_time)
                .map(|next| {
                    ((presentation_time_ms - f64::from(current.server_time))
                        / f64::from(next.server_time - current.server_time)) as f32
                })
                .unwrap_or(0.0)
                .clamp(0.0, 1.0)
        };

        let current_origin = playerstate_vec3(&current.player_state, "origin")?;
        let current_angles = playerstate_vec3(&current.player_state, "viewangles")?;
        let current_viewheight = current
            .player_state
            .field_i32("viewheight")
            .unwrap_or(0) as f32;

        let (origin, angles, viewheight) = if let Some(next) = next {
            let next_origin = playerstate_vec3(&next.player_state, "origin")
                .unwrap_or(current_origin);
            let next_angles = playerstate_vec3(&next.player_state, "viewangles")
                .unwrap_or(current_angles);
            let next_viewheight = next
                .player_state
                .field_i32("viewheight")
                .unwrap_or(current_viewheight as i32) as f32;
            (
                lerp_vec3(current_origin, next_origin, alpha),
                [
                    lerp_angle_degrees(current_angles[0], next_angles[0], alpha),
                    lerp_angle_degrees(current_angles[1], next_angles[1], alpha),
                    lerp_angle_degrees(current_angles[2], next_angles[2], alpha),
                ],
                current_viewheight + (next_viewheight - current_viewheight) * alpha,
            )
        } else {
            (current_origin, current_angles, current_viewheight)
        };

        let mut eye = origin;
        eye[2] += viewheight;
        Some(DemoCameraSample {
            server_time,
            presentation_time_ms,
            native_origin: origin,
            eye_position: scene::render_position(eye),
            player_position: scene::render_position(origin),
            view_angles: angles,
            view_height: viewheight.round() as i32,
            dead_yaw: current.player_state.stats.get(6).copied().unwrap_or(0) as f32,
            client_num: current.player_state.field_i32("clientNum").unwrap_or(0),
            policy: PlayerViewPolicyState::from_player_state(&current.player_state),
            teleported,
        })
    }
}

/// Camera sample for cg.predictedPlayerState (CG_CalcViewValues adds the
/// decaying prediction error to the view origin only).
fn sample_player_state(
    ps: &jka_protocol::server::PlayerState,
    server_time: i32,
    teleported: bool,
    error: [f32; 3],
) -> Option<DemoCameraSample> {
    let origin = playerstate_vec3(ps, "origin")?;
    let view_angles = playerstate_vec3(ps, "viewangles")?;
    let view_height = ps.field_i32("viewheight").unwrap_or(0);
    let view_origin = [origin[0] + error[0], origin[1] + error[1], origin[2] + error[2]];
    let mut eye = view_origin;
    eye[2] += view_height as f32;
    Some(DemoCameraSample {
        server_time,
        presentation_time_ms: f64::from(server_time),
        native_origin: view_origin,
        eye_position: scene::render_position(eye),
        player_position: scene::render_position(origin),
        view_angles,
        view_height,
        dead_yaw: ps.stats.get(6).copied().unwrap_or(0) as f32,
        client_num: ps.field_i32("clientNum").unwrap_or(0),
        policy: PlayerViewPolicyState::from_player_state(ps),
        teleported,
    })
}

fn playerstate_vec3(state: &jka_protocol::server::PlayerState, base: &str) -> Option<[f32; 3]> {
    Some([
        state.field_f32(&format!("{base}[0]"))?,
        state.field_f32(&format!("{base}[1]"))?,
        state.field_f32(&format!("{base}[2]"))?,
    ])
}

fn lerp_vec3(a: [f32; 3], b: [f32; 3], alpha: f32) -> [f32; 3] {
    [
        a[0] + (b[0] - a[0]) * alpha,
        a[1] + (b[1] - a[1]) * alpha,
        a[2] + (b[2] - a[2]) * alpha,
    ]
}

fn lerp_angle_degrees(a: f32, b: f32, alpha: f32) -> f32 {
    let delta = (b - a + 180.0).rem_euclid(360.0) - 180.0;
    a + delta * alpha
}

/// Half-extent of the box drawn for a point entity (no brush model) by
/// `r_drawEntities` — shared by the mesh builder and the trace hit test so
/// what you can click always matches what you see.
const ENTITY_MARKER_POINT_HALF_SIZE: f32 = 8.0;

/// World-space AABB `r_drawEntities` draws for one entity, given its already
/// live-corrected `origin` (see `App::live_entity_origin`).
fn entity_marker_box(entity: &crate::entity_graph::GraphEntity, origin: [f32; 3]) -> ([f32; 3], [f32; 3]) {
    match entity.bounds {
        Some((bounds_mins, bounds_maxs)) => {
            let half: [f32; 3] = std::array::from_fn(|axis| (bounds_maxs[axis] - bounds_mins[axis]) * 0.5);
            (
                std::array::from_fn(|axis| origin[axis] - half[axis]),
                std::array::from_fn(|axis| origin[axis] + half[axis]),
            )
        }
        None => (
            std::array::from_fn(|axis| origin[axis] - ENTITY_MARKER_POINT_HALF_SIZE),
            std::array::from_fn(|axis| origin[axis] + ENTITY_MARKER_POINT_HALF_SIZE),
        ),
    }
}

/// Slab-method ray/AABB intersection. Returns the entry distance along `dir`
/// (which need not be normalized-length-aware by the caller; callers here
/// only compare distances against each other, never against a world unit
/// budget), or `None` when the ray starts past the box or misses it entirely.
fn ray_aabb_distance(origin: [f32; 3], dir: [f32; 3], mins: [f32; 3], maxs: [f32; 3]) -> Option<f32> {
    let mut tmin = 0.0f32;
    let mut tmax = f32::MAX;
    for axis in 0..3 {
        if dir[axis].abs() < 1e-6 {
            if origin[axis] < mins[axis] || origin[axis] > maxs[axis] {
                return None;
            }
            continue;
        }
        let inv = 1.0 / dir[axis];
        let (mut t1, mut t2) = ((mins[axis] - origin[axis]) * inv, (maxs[axis] - origin[axis]) * inv);
        if t1 > t2 {
            std::mem::swap(&mut t1, &mut t2);
        }
        tmin = tmin.max(t1);
        tmax = tmax.min(t2);
        if tmin > tmax {
            return None;
        }
    }
    // `tmin` sticks at its 0.0 initial value exactly when the origin is
    // already inside the box on every axis (it never found a positive entry
    // time). Standing inside a room-sized trigger volume is normal; that
    // should not hijack every trace until the player walks back out of it.
    (tmin > 0.0).then_some(tmin)
}

