enum LiveDownloadTransfer {
    Idle,
    Http {
        rx: Receiver<crate::download::HttpEvent>,
    },
    Legacy {
        file: File,
        temp_path: PathBuf,
        expected_block: u16,
        received: u64,
        total: Option<u64>,
    },
}

