    fn current_demo_elapsed_ms(&self, now: Instant) -> Option<f64> {
        self.game_session
            .as_ref()
            .filter(|session| !session.live)
            .and_then(|session| session.demo_elapsed_ms(now))
    }

    fn transient_ui_snapshot(&self) -> (Vec<UiChatLine>, Option<ui::UiCenterPrint>) {
        let now = Instant::now();
        let demo_now = self.current_demo_elapsed_ms(now);
        let chat_lines = self
            .chat_lines
            .iter()
            .filter_map(|line| {
                let age_ms = match (demo_now, line.demo_elapsed_ms) {
                    (Some(now_ms), Some(created_ms)) => (now_ms - created_ms).max(0.0),
                    _ => now.saturating_duration_since(line.created).as_secs_f64() * 1000.0,
                };
                // Stock MP cg_chatBox defaults to 10000 ms. Demo messages age
                // against demo time, so pause/scrub is deterministic and cannot flicker.
                if age_ms >= 10_000.0 {
                    return None;
                }
                let alpha = if age_ms <= 9_000.0 {
                    1.0
                } else {
                    1.0 - ((age_ms - 9_000.0) / 1_000.0) as f32
                };
                Some(UiChatLine {
                    text: line.text.clone(),
                    alpha: alpha.clamp(0.0, 1.0),
                })
            })
            .collect();

        let center_print = self.center_print.as_ref().and_then(|print| {
            const CENTER_TIME: Duration = Duration::from_secs(3);
            const FADE_TIME: Duration = Duration::from_millis(200);
            let age = match (demo_now, print.demo_elapsed_ms) {
                (Some(now_ms), Some(created_ms)) => Duration::from_secs_f64(((now_ms - created_ms).max(0.0)) / 1000.0),
                _ => now.saturating_duration_since(print.created),
            };
            if age >= CENTER_TIME {
                return None;
            }
            let remaining = CENTER_TIME.saturating_sub(age);
            let alpha = if remaining < FADE_TIME {
                remaining.as_secs_f32() / FADE_TIME.as_secs_f32()
            } else {
                1.0
            };
            Some(ui::UiCenterPrint { text: print.text.clone(), alpha, y_fraction: print.y_fraction })
        });

        (chat_lines, center_print)
    }

    fn restore_demo_transients(&mut self, elapsed_ms: i32, now: Instant) {
        let notices = self
            .game_session
            .as_ref()
            .and_then(|session| session.demo_index.as_ref())
            .map(|index| index.transient_notices.clone())
            .unwrap_or_default();
        self.chat_lines.clear();
        self.center_print = None;
        self.last_center_print.clear();

        let chat_start = elapsed_ms.saturating_sub(10_000);
        for entry in notices.iter().filter(|entry| {
            entry.kind == DemoConsoleKind::Chat
                && entry.elapsed_ms >= chat_start
                && entry.elapsed_ms <= elapsed_ms
        }).rev().take(16).collect::<Vec<_>>().into_iter().rev() {
            self.chat_lines.push_back(ChatRecord {
                text: entry.text.clone(),
                created: now,
                demo_elapsed_ms: Some(f64::from(entry.elapsed_ms)),
            });
        }
        if let Some(entry) = notices.iter().rev().find(|entry| {
            entry.kind == DemoConsoleKind::CenterPrint
                && entry.elapsed_ms <= elapsed_ms
                && elapsed_ms.saturating_sub(entry.elapsed_ms) < 3_000
        }) {
            let rendered = self.translate_server_text(entry.text.as_bytes());
            self.center_print = Some(CenterPrintRecord {
                text: rendered,
                created: now,
                demo_elapsed_ms: Some(f64::from(entry.elapsed_ms)),
                y_fraction: 0.30,
            });
        }
        self.last_chat_refresh = now;
        self.last_center_refresh = now;
    }

    fn demo_timeline_ui(&self, now: Instant) -> Option<DemoTimelineUi> {
        let session = self
            .game_session
            .as_ref()
            .filter(|session| !session.live && session.phase == SessionPhase::Playing)?;
        let index = session.demo_index.as_ref()?;
        let first = index.first_active_server_time?;
        let duration_ms = index.duration_ms();
        if duration_ms <= 0 {
            return None;
        }
        let authoritative = session.demo_followed_client().unwrap_or(-1);
        let followed = match self.demo_view_mode {
            DemoViewMode::Follow(client) => client,
            _ => authoritative,
        };
        let duration = duration_ms as f32;
        let kill_markers = index
            .kill_markers
            .iter()
            .map(|marker| DemoKillMarkerUi {
                fraction: (marker.server_time.saturating_sub(first) as f32 / duration).clamp(0.0, 1.0),
                attacker_team: marker.attacker_team,
                followed_kill: marker.attacker == followed && marker.target != followed,
                followed_death: marker.target == followed,
            })
            .collect();
        let (paused, playback_rate) = session
            .timeline
            .map(|timeline| {
                let paused = timeline.rate == 0.0;
                let speed = if paused { timeline.resume_rate } else { timeline.rate };
                (paused, speed)
            })
            .unwrap_or((true, 1.0));
        let camera_label = match self.demo_view_mode {
            DemoViewMode::Authoritative => session.demo_visible_players().into_iter()
                .find(|(client, _)| *client == authoritative)
                .map(|(_, name)| format!("RECORDED: {name}"))
                .unwrap_or_else(|| "RECORDED POV".to_owned()),
            DemoViewMode::Follow(client) => session.demo_visible_players().into_iter()
                .find(|(candidate, _)| *candidate == client)
                .map(|(_, name)| format!("FAKE POV: {name}"))
                .unwrap_or_else(|| format!("FAKE POV: CLIENT {client}")),
            DemoViewMode::Free => "FREE VIEW".to_owned(),
        };
        Some(DemoTimelineUi {
            elapsed_ms: session.demo_elapsed_ms(now).unwrap_or(0.0),
            duration_ms,
            playback_rate,
            paused,
            scrub_fraction: self.demo_scrub_fraction,
            kill_markers,
            camera_label,
            outside_authoritative_view: self.demo_view_outside_authoritative,
        })
    }

    fn ui_snapshot(&self) -> UiSnapshot {
        // Keep the retained UI snapshot bounded even after a very long console session.
        // Full-screen 4K needs far fewer than 384 atlas-text rows, so this leaves
        // ample scroll context without cloning the entire 10k-line ring every keypress.
        let console_scroll = self.console_scroll.min(self.console_max_scroll());
        let console_end = self.console_lines.len().saturating_sub(console_scroll);
        let console_start = console_end.saturating_sub(384);
        let console_lines: Vec<String> = self
            .console_lines
            .iter()
            .skip(console_start)
            .take(console_end - console_start)
            .cloned()
            .collect();
        let console_selection = match (self.console_selection_anchor, self.console_selection_focus) {
            (Some(mut start), Some(mut end)) if console_start < console_end => {
                if (start.line, start.col) > (end.line, end.col) {
                    std::mem::swap(&mut start, &mut end);
                }
                if end.line < console_start || start.line >= console_end {
                    None
                } else {
                    if start.line < console_start {
                        start = ConsolePoint {
                            line: console_start,
                            col: 0,
                        };
                    }
                    if end.line >= console_end {
                        let line = console_end - 1;
                        let col = self
                            .console_lines
                            .get(line)
                            .map(|raw| crate::logging::strip_jka_colors(raw).chars().count())
                            .unwrap_or(0);
                        end = ConsolePoint { line, col };
                    }
                    Some(ConsoleSelection {
                        start_line: start.line - console_start,
                        start_col: start.col,
                        end_line: end.line - console_start,
                        end_col: end.col,
                    })
                }
            }
            _ => None,
        };

        let console_search_matches: Vec<ConsoleSearchMatch> = self
            .console_search_matches
            .iter()
            .filter(|hit| hit.line >= console_start && hit.line < console_end)
            .map(|hit| ConsoleSearchMatch {
                line: hit.line - console_start,
                start_col: hit.start_col,
                end_col: hit.end_col,
            })
            .collect();
        let console_search_active = self
            .console_search_index
            .and_then(|index| self.console_search_matches.get(index).copied())
            .and_then(|hit| {
                (hit.line >= console_start && hit.line < console_end).then_some(
                    ConsoleSearchMatch {
                        line: hit.line - console_start,
                        start_col: hit.start_col,
                        end_col: hit.end_col,
                    },
                )
            });
        let console_path_links: Vec<ConsolePathLinkUi> = self
            .console_path_links
            .iter()
            .enumerate()
            .skip(console_start)
            .take(console_end - console_start)
            .flat_map(|(line, links)| {
                links.iter().map(move |link| ConsolePathLinkUi {
                    line: line - console_start,
                    start_col: link.start_col,
                    end_col: link.end_col,
                })
            })
            .collect();

        let (mut chat_lines, mut center_print) = self.transient_ui_snapshot();
        let hud = self.current_hud_state();
        let mut follow_name = self.current_follow_name();
        let mut race_timer = self.game_session.as_ref().and_then(|session| session.race_timer_ui.clone());
        let mut vote_line = self.vote_hud_line();
        let mut crosshair_target = self.crosshair_target.clone();
        let mut surface_inspector = self.surface_inspector.clone();
        let mut speedometer = self.speedometer_ui.clone();
        if self.overlay == OverlayMode::HudEdit {
            self.hud_edit_transient_samples(
                &mut chat_lines,
                &mut center_print,
                &mut follow_name,
                &mut vote_line,
                &mut crosshair_target,
                &mut race_timer,
                &mut speedometer,
            );
            surface_inspector.get_or_insert_with(|| SurfaceInspectorInfo {
                kind: "WORLD SURFACE".to_owned(),
                title: "textures/sample/trace_inspector".to_owned(),
                summary: vec![
                    ("SHADER".to_owned(), "textures/sample/trace_inspector".to_owned()),
                    ("DISTANCE".to_owned(), "128.0 units".to_owned()),
                    ("SURFACE".to_owned(), "12345".to_owned()),
                ],
                sections: Vec::new(),
                lines: Vec::new(),
                hit_entity_num: None,
                hit_inline_model: None,
            });
        }
        let (console_suggestions, console_suggest_total, console_suggest_hint) =
            self.console_suggest_snapshot();
        let console_suggest_selected = if self.console_suggest_picked {
            self.console_suggest_index.min(console_suggestions.len().saturating_sub(1))
        } else {
            0
        };
        let prediction_debug = self.prediction_debug_ui();

        UiSnapshot {
            mode: self.overlay,
            setup_selected: self.setup_selected,
            console_input: self.console_input.clone(),
            console_cursor: self.console_cursor,
            console_status: self.console_status.clone(),
            console_lines,
            console_scroll: 0,
            console_size: self.console_size,
            console_selection,
            console_search_open: self.console_search_open,
            console_search_query: self.console_search_input.clone(),
            console_search_total: self.console_search_matches.len(),
            console_search_index: self.console_search_index,
            console_search_matches,
            console_search_active,
            console_path_links,
            console_total_lines: self.console_lines.len(),
            console_scrolled: console_scroll,
            console_suggest_enabled: self.console_suggest,
            console_suggestions,
            console_suggest_total,
            console_suggest_selected,
            console_suggest_hint,
            console_help_hover: self.console_help_hover && self.overlay == OverlayMode::Console,
            chat_mode: self.chat_mode,
            chat_input: self.chat_input.clone(),
            chat_lines,
            center_print,
            follow_name,
            race_timer,
            vote_line,
            scoreboard: self.scores_showing.then(|| self.scoreboard.clone()).flatten(),
            demo_timeline: self.demo_timeline_ui(Instant::now()),
            prediction_debug,
            hud,
            hud_layout: self.hud_layout,
            crosshair: self.crosshair,
            crosshair_target,
            movement_keys: self.movement_keys_hud,
            strafe_helper: self.strafe_helper,
            movement_hud: self.current_movement_hud_state(),
            speedometer,
            lagometer: self.lagometer_ui.clone(),
            video: self.video,
            perf: self.perf,
            threads: self.threads,
            surface_inspector,
            startup_splash: !self.startup_first_frame_seen,
            loading: self.loading.as_ref().map(MapLoadingState::ui),
            static_ao_progress: self.static_ao_progress.map(|(completed, total)| MapLoadingBar {
                label: "BAKED AO",
                completed,
                total,
                skipped: false,
            }),
        }
    }

    /// HUD Edit Mode: fill the normally empty transient readouts with sample
    /// content so there is something to grab and to see move. Shared by the full
    /// snapshot and the transient republish so neither wipes the other's samples.
    #[allow(clippy::too_many_arguments)]
    fn hud_edit_transient_samples(
        &self,
        chat_lines: &mut Vec<ui::UiChatLine>,
        center_print: &mut Option<ui::UiCenterPrint>,
        follow_name: &mut Option<String>,
        vote_line: &mut Option<String>,
        crosshair_target: &mut ui::UiCrosshairTarget,
        race_timer: &mut Option<crate::japro_cg::RaceTimerUi>,
        speedometer: &mut Option<crate::speedometer::Ui>,
    ) {
        if chat_lines.is_empty() {
            *chat_lines = ["^7Player^7: chat messages appear here", "^7Another^7: drag this block anywhere"]
                .map(|text| ui::UiChatLine { text: text.to_owned(), alpha: 1.0 })
                .into();
        }
        center_print.get_or_insert_with(|| ui::UiCenterPrint { text: "Center print text".to_owned(), alpha: 1.0, y_fraction: 0.30 });
        follow_name.get_or_insert_with(|| "Followed Player".to_owned());
        vote_line.get_or_insert_with(|| "Vote (30): map ffa_bespin  Yes: 1  No: 0".to_owned());
        if crosshair_target.name.is_none() {
            crosshair_target.name = Some(ui::UiCrosshairName {
                text: "Target Player".to_owned(),
                color: [1.0, 1.0, 1.0],
                alpha: 1.0,
            });
        }
        race_timer.get_or_insert_with(|| crate::japro_cg::RaceTimerUi {
            timer_text: "0:12.3\nMax: 640\nAvg: 512".to_owned(),
            timer_x: self.japro_cg.race_timer_x,
            timer_y: self.japro_cg.race_timer_y,
            size: self.japro_cg.race_timer_size,
            start_text: "Start: 420".to_owned(),
            start_x: self.japro_cg.race_start_x,
            start_y: self.japro_cg.race_start_y,
            start_color: [1.0; 3],
        });
        speedometer.get_or_insert_with(|| crate::speedometer::preview(&self.japro_cg.speedometer));
    }

    fn prediction_debug_ui(&self) -> Option<PredictionDebugUi> {
        if !self.network.prediction_debug && !self.network.prediction_miss_highlight {
            return None;
        }

        if self.game_session.as_ref().is_some_and(|session| session.local) {
            let mut lines = vec!["SOLO GAME: local physics / snapshot presentation".to_owned()];
            if let Some(server) = self.local_server.as_ref() {
                let view = server.view();
                lines.push(format!(
                    "physics t={} ground={} z={:.3} vZ={:.3} legs={} torso={}",
                    view.command_time, view.ground_entity, view.origin[2], view.velocity[2],
                    view.legs_anim, view.torso_anim,
                ));
            }
            if let Some(session) = self.game_session.as_ref() {
                if let Some(entity) = session.audio_followed_entity.as_ref() {
                    lines.push(format!(
                        "presentation ground={} z={:.3} legs={} torso={}",
                        entity.state.field_i32("groundEntityNum").unwrap_or(1023), entity.origin[2],
                        entity.state.field_i32("legsAnim").unwrap_or(0),
                        entity.state.field_i32("torsoAnim").unwrap_or(0),
                    ));
                }
                if let Some(anim) = session.player_presenter.viewer_anim_debug() {
                    lines.push(format!(
                        "pose t={} call={} legs frame={}/{} blend={:.3} torso frame={}/{} blend={:.3}",
                        anim.pose_time, anim.call_time, anim.legs_frame, anim.legs_old_frame,
                        anim.legs_backlerp, anim.torso_frame, anim.torso_old_frame, anim.torso_backlerp,
                    ));
                }
            }
            lines.push("ground IDs: 1022=world, 1023=none; online ground traces unavailable here".to_owned());
            return Some(PredictionDebugUi {
                show_panel: self.network.prediction_debug, flash: false,
                threshold: self.network.prediction_miss_threshold, last_miss: None, lines,
            });
        }

        let frame = self.predictor.prediction_debug_frame();
        let miss = self.predictor.latest_prediction_miss();
        let threshold = self.network.prediction_miss_threshold;
        let flash = self.network.prediction_miss_highlight
            && miss.is_some_and(|miss| {
                miss.length >= threshold && miss.detected_at.elapsed() <= Duration::from_millis(350)
            });
        let mut lines = Vec::new();

        if let Some(frame) = frame {
            let view_error_len = frame.view_error.iter().map(|v| v * v).sum::<f32>().sqrt();
            lines.push(format!(
                "NOW t={} display o=[{:.2} {:.2} {:.2}] vZ={:.2} ground={} pm={} flags={:#x} scale={}",
                frame.server_time,
                frame.display.origin[0], frame.display.origin[1], frame.display.origin[2],
                frame.display.velocity[2], frame.display.ground_entity, frame.display.pm_type,
                frame.display.pm_flags, frame.display.model_scale,
            ));
            lines.push(format!(
                "view correction=[{:.2} {:.2} {:.2}] |corr|={:.2}  committed ground={} legs={} torso={} inAir={}",
                frame.view_error[0], frame.view_error[1], frame.view_error[2], view_error_len,
                frame.committed.ground_entity, frame.committed.legs_anim,
                frame.committed.torso_anim, frame.committed.in_air_anim,
            ));
            if let Some(trace) = frame.ground_trace {
                lines.push(format!(
                    "groundTrace .25: frac={:.4} ent={} ss={} as={} hitZ={:.2} n=[{:.2} {:.2} {:.2}]",
                    trace.fraction, trace.entity, u8::from(trace.start_solid), u8::from(trace.all_solid),
                    trace.hit_end[2], trace.normal[0], trace.normal[1], trace.normal[2],
                ));
            }
            if let Some(trace) = frame.ground_probe {
                lines.push(format!(
                    "groundProbe 64: frac={:.4} ent={} ss={} as={} hitZ={:.2} nZ={:.2}",
                    trace.fraction, trace.entity, u8::from(trace.start_solid), u8::from(trace.all_solid),
                    trace.hit_end[2], trace.normal[2],
                ));
            }
        } else {
            lines.push("prediction frame unavailable (cg_noPredict/follow/no live predictor)".to_owned());
        }

        if let Some(miss) = miss {
            lines.push(format!(
                "MISS #{} age={}ms len={:.3} delta=[{:.3} {:.3} {:.3}] cmd={}",
                miss.sequence, miss.detected_at.elapsed().as_millis(), miss.length,
                miss.delta[0], miss.delta[1], miss.delta[2], miss.command_time,
            ));
            lines.push(format!(
                "pred o=[{:.2} {:.2} {:.2}] v=[{:.2} {:.2} {:.2}] ground={} pm={} legs={} scale={}",
                miss.predicted.origin[0], miss.predicted.origin[1], miss.predicted.origin[2],
                miss.predicted.velocity[0], miss.predicted.velocity[1], miss.predicted.velocity[2],
                miss.predicted.ground_entity, miss.predicted.pm_type, miss.predicted.legs_anim,
                miss.predicted.model_scale,
            ));
            lines.push(format!(
                "srv  o=[{:.2} {:.2} {:.2}] v=[{:.2} {:.2} {:.2}] ground={} pm={} legs={} scale={}",
                miss.server.origin[0], miss.server.origin[1], miss.server.origin[2],
                miss.server.velocity[0], miss.server.velocity[1], miss.server.velocity[2],
                miss.server.ground_entity, miss.server.pm_type, miss.server.legs_anim,
                miss.server.model_scale,
            ));
            let trace_line = |label: &str, trace: crate::net::PredictionTraceDebug| {
                format!(
                    "{label}: {:.2}->{:.2} frac={:.4} hitZ={:.2} ent={} ss={} as={} nZ={:.2}",
                    trace.start[2], trace.end[2], trace.fraction, trace.hit_end[2], trace.entity,
                    u8::from(trace.start_solid), u8::from(trace.all_solid), trace.normal[2],
                )
            };
            if let Some(trace) = miss.previous_ground_trace {
                lines.push(trace_line("pre-miss ground .25", trace));
            }
            if let Some(trace) = miss.previous_ground_probe {
                lines.push(trace_line("pre-miss probe 64", trace));
            }
            if let Some(trace) = miss.replay_ground_trace {
                lines.push(trace_line("replay ground .25", trace));
            }
            if let Some(trace) = miss.replay_ground_probe {
                lines.push(trace_line("replay probe 64", trace));
            }
        }

        Some(PredictionDebugUi {
            show_panel: self.network.prediction_debug,
            flash,
            threshold,
            last_miss: miss.map(|miss| miss.length),
            lines,
        })
    }

    fn subframe_input_view_rotation(&self) -> Option<[f32; 2]> {
        if !self.video.input_subframe {
            return None;
        }
        if !self.live_remote_view_forced() {
            if let Some(angles) = self.live_view_angles() {
                return Some([angles[1].to_radians(), -angles[0].to_radians()]);
            }
        }
        self.local_server.as_ref().and_then(|server| {
            if server.view().view_forced != 0 {
                return None;
            }
            let angles = server.subframe_view_angles();
            Some([angles[1].to_radians(), -angles[0].to_radians()])
        })
    }

    fn render_snapshot(&self) -> RenderSnapshot {
        let demo_player_position = self
            .game_session
            .as_ref()
            .and_then(|playback| playback.player_position);
        let dynamic_models = if self.profile_preview_active {
            Arc::clone(&self.profile_dynamic_models)
        } else {
            self
            .game_session
            .as_ref()
            .map(|playback| {
                if playback.fx_surfaces.is_empty() {
                    Arc::clone(&playback.dynamic_models)
                } else {
                    let mut merged = Vec::with_capacity(playback.dynamic_models.len() + playback.fx_surfaces.len());
                    merged.extend(playback.dynamic_models.iter().cloned());
                    merged.extend(playback.fx_surfaces.iter().cloned());
                    Arc::new(merged)
                }
            })
            .unwrap_or_else(|| Arc::clone(&self.solo_dynamic_models))
        };
        let dynamic_models = if self.overlay == OverlayMode::MapEdit {
            if let Some(preview) = self.map_editor.as_ref().and_then(MapEditor::preview_surface) {
                let mut merged = Vec::with_capacity(dynamic_models.len() + 1);
                merged.extend(dynamic_models.iter().cloned());
                merged.push(preview);
                Arc::new(merged)
            } else {
                Arc::clone(&dynamic_models)
            }
        } else {
            dynamic_models
        };
        // CGame owns mover state once it has a snapshot (demo, live, or the
        // solo shim, which spawns brush entities as ET_MOVERs); before that
        // inline models keep their compiled pose.
        let inline_models = self
            .game_session
            .as_ref()
            .filter(|playback| playback.current_snapshot.is_some())
            .map(|playback| Arc::clone(&playback.inline_models));
        let input_view_rotation = self.subframe_input_view_rotation();
        RenderSnapshot {
            model_frame_source: self.network.model_frame_debug.then(|| {
                let playback = self.game_session.as_ref();
                crate::model_frame_log::FrameSource::new(
                    playback.and_then(|s| s.audio_followed_entity.as_ref()).map_or(1023, |e| e.number),
                    playback.and_then(|s| s.player_presenter.viewer_anim_debug()),
                )
            }),
            camera: if self.profile_preview_active
                || (self.front_end && self.frontend_page == FrontendPage::AssetViewer)
            {
                self.asset_preview_camera()
            } else {
                let mut camera = self.camera;
                camera.set_presentation_fov(self.japro_effective_fov(Instant::now()));
                if let Some(playback) = self.game_session.as_ref() {
                    // Render space is Y-up: landing dip and stair smoothing move the eye vertically.
                    camera.position.y += playback.view_offset_z;
                }
                camera
            },
            view_latch: if self.front_end || input_view_rotation.is_none() {
                ViewLatchMode::Disabled
            } else {
                self.render_view_latch
            },
            input_view_rotation,
            player_position: demo_player_position
                .or_else(|| self.local_server.as_ref().map(LocalServer::world_position)),
            area_mask: self
                .game_session
                .as_ref()
                .and_then(|playback| playback.current_snapshot.as_ref())
                .map(|snapshot| snapshot.area_mask),
            dynamic_models,
            transient_lights: if self.profile_preview_active {
                Arc::new(Vec::new())
            } else {
                self.game_session
                    .as_ref()
                    .map_or_else(|| Arc::new(Vec::new()), |playback| Arc::clone(&playback.fx_lights))
            },
            screen_fx: self
                .game_session
                .as_ref()
                .map_or_else(|| Arc::new(Vec::new()), |playback| Arc::clone(&playback.screen_fx)),
            cloud_foreground: if self.profile_preview_active {
                Arc::new(Vec::new())
            } else {
                self.game_session
                    .as_ref()
                    .map_or_else(|| Arc::new(Vec::new()), |playback| Arc::clone(&playback.fx_blades))
            },
            inline_models,
            dof_focus_target: self.dof_focus_target,
            input_latency: self.last_simulated_mouse_input,
            client_perf: self
                .game_session
                .as_ref()
                .map_or_else(ClientFramePerf::default, |playback| playback.client_perf),
            hud: self.current_hud_state(),
            movement_hud: self.current_movement_hud_state(),
            jump_shade: self.current_jump_shade(),
            camera_shake: self
                .game_session
                .as_ref()
                .and_then(|playback| playback.event_presenter.camera_shake()),
        }
    }

    /// CG_OutOfAmmoChange for EV_NOAMMO events the session queued.
    fn apply_out_of_ammo_changes(&mut self) {
        let auto_switch = self.audio.game.auto_switch;
        let Some(session) = self.game_session.as_mut() else { return };
        if session.pending_out_of_ammo.is_empty() && session.pending_weapon_select.is_empty() {
            return;
        }
        let pending = std::mem::take(&mut session.pending_out_of_ammo);
        let picked = std::mem::take(&mut session.pending_weapon_select);
        let Some(snapshot) = session.current_snapshot.as_ref() else { return };
        if auto_switch > 0 {
            for (old, dry) in pending {
                let mut ps = snapshot.player_state.clone();
                if dry > 0 {
                    ps.stats[4] &= !(1 << dry);
                }
                self.live_input.out_of_ammo_change(&ps, old, auto_switch);
            }
        }
        for tag in picked {
            self.live_input.pickup_autoswitch(&snapshot.player_state, tag, auto_switch);
        }
    }

    fn publish_snapshot(&self) {
        if let Some(render) = &self.render {
            render.publish(self.render_snapshot());
        }
    }

    /// Feed the render-only latest-view mailbox directly from live mouse input.
    /// The mailbox always contains raw local viewangles; RenderSnapshot::view_latch
    /// decides whether they map directly to first person or through the cheap
    /// no-trace portion of the existing OpenJK third-person camera.
    fn publish_live_subframe_view(&self, input: InputLatencySample) {
        if !self.video.input_subframe || self.live_remote_view_forced() {
            return;
        }
        let Some(view_angles) = self.live_view_angles() else {
            return;
        };
        if let Some(render) = &self.render {
            render.publish_subframe_view_rotation(
                view_angles[1].to_radians(),
                -view_angles[0].to_radians(),
                input,
            );
        }
    }

    fn publish_local_subframe_view(&self, input: InputLatencySample) -> bool {
        if !self.video.input_subframe {
            return false;
        }
        let Some(server) = self.local_server.as_ref() else {
            return false;
        };
        let player_view = server.view();
        if player_view.view_forced != 0 {
            return false;
        }
        let entity_view = server.entity_view();
        let policy = PlayerViewPolicyState::from_entity_view(entity_view, player_view.legs_timer);
        if rendering_third_person(self.third_person, self.first_person_lightsaber, policy)
            && !matches!(self.render_view_latch, ViewLatchMode::ThirdPerson(_))
        {
            // Around a wall, during camera damping, or on the first camera frame,
            // keep the pre-existing local fallback that reruns the authoritative
            // CGame camera instead of using an untraced third-person orbit.
            return false;
        }
        let view_angles = server.subframe_view_angles();
        if let Some(render) = &self.render {
            render.publish_subframe_view_rotation(
                view_angles[1].to_radians(),
                -view_angles[0].to_radians(),
                input,
            );
            return true;
        }
        false
    }

    fn publish_ui(&self) {
        if self.settings_batch_open {
            self.ui_publish_pending.set(true);
            return;
        }
        self.render_command(RenderCommand::SetUi(self.ui_snapshot()));
    }

    /// Start a batch of settings changes. The renderer defers pipeline-variant
    /// activation and this side coalesces UI snapshots until `end_settings_batch`.
    fn begin_settings_batch(&mut self, title: &str) {
        self.settings_batch_open = true;
        self.render_command(RenderCommand::BatchBegin(title.to_owned()));
    }

    fn end_settings_batch(&mut self) {
        self.settings_batch_open = false;
        if self.ui_publish_pending.take() {
            self.publish_ui();
        }
        self.render_command(RenderCommand::BatchEnd);
    }

    fn publish_transient_ui(&self) {
        let (mut chat_lines, mut center_print) = self.transient_ui_snapshot();
        let demo_timeline = self.demo_timeline_ui(Instant::now());
        let prediction_debug = self.prediction_debug_ui();
        let mut crosshair_target = self.crosshair_target.clone();
        let mut follow_name = self.current_follow_name();
        let mut race_timer = self
            .game_session
            .as_ref()
            .and_then(|session| session.race_timer_ui.clone());
        let mut vote_line = self.vote_hud_line();
        let mut speedometer = self.speedometer_ui.clone();
        if self.overlay == OverlayMode::HudEdit {
            self.hud_edit_transient_samples(
                &mut chat_lines,
                &mut center_print,
                &mut follow_name,
                &mut vote_line,
                &mut crosshair_target,
                &mut race_timer,
                &mut speedometer,
            );
        }
        self.render_command(RenderCommand::SetTransientUi {
            chat_lines,
            center_print,
            demo_timeline,
            prediction_debug,
            crosshair_target,
            follow_name,
            race_timer,
            vote_line,
            speedometer,
            lagometer: self.lagometer_ui.clone(),
        });
    }

    fn publish_telemetry_ui(&self) {
        self.render_command(RenderCommand::SetUiTelemetry {
            perf: self.perf,
            threads: self.threads,
        });
    }

    fn render_command(&self, command: RenderCommand) {
        if let Some(render) = &self.render {
            render.command(command);
        }
    }

    fn demo_playback_active(&self) -> bool {
        self.game_session.as_ref().is_some_and(|session| {
            !session.live && session.phase == SessionPhase::Playing && session.demo_index.is_some()
        })
    }

    fn demo_timeline_hit(&self, x: f64, y: f64) -> Option<DemoTimelineHit> {
        if !self.demo_playback_active() || self.overlay != OverlayMode::None {
            return None;
        }
        let size = self.window.as_ref()?.inner_size();
        let layout = ui::demo_timeline_layout(size.width, size.height)?;
        let point = [x as f32, y as f32];
        let inside = |rect: [f32; 4]| {
            point[0] >= rect[0]
                && point[0] <= rect[0] + rect[2]
                && point[1] >= rect[1]
                && point[1] <= rect[1] + rect[3]
        };
        if inside(layout.play) {
            return Some(DemoTimelineHit::PlayPause);
        }
        if inside(layout.speed) {
            return Some(DemoTimelineHit::Speed);
        }
        if inside(layout.track) {
            let fraction = ((point[0] - layout.track[0]) / layout.track[2]).clamp(0.0, 1.0);
            return Some(DemoTimelineHit::Track(fraction));
        }
        None
    }

    fn toggle_demo_pause_ui(&mut self) {
        let status = self.game_session.as_mut().and_then(|session| {
            (!session.live).then(|| session.toggle_pause(Instant::now())).and_then(Result::ok)
        });
        if let Some(rate) = status {
            self.console_status = if rate == 0.0 {
                "DEMO PAUSED".into()
            } else {
                format!("DEMO PLAYING AT {rate}X")
            };
            self.publish_transient_ui();
        }
    }

    fn cycle_demo_speed_ui(&mut self) {
        const RATES: [f64; 5] = [0.25, 0.5, 1.0, 2.0, 4.0];
        let Some(session) = self.game_session.as_mut().filter(|session| !session.live) else { return; };
        let current = session.timeline.map(|timeline| {
            if timeline.rate > 0.0 { timeline.rate } else { timeline.resume_rate }
        }).unwrap_or(1.0);
        let next = RATES
            .iter()
            .copied()
            .find(|rate| *rate > current + 0.001)
            .unwrap_or(RATES[0]);
        if session.set_playback_speed(Instant::now(), next).is_ok() {
            self.console_status = format!("DEMO SPEED: {next}X");
            self.publish_transient_ui();
        }
    }

    fn lower_demo_speed_ui(&mut self) {
        const RATES: [f64; 5] = [0.25, 0.5, 1.0, 2.0, 4.0];
        let Some(session) = self.game_session.as_mut().filter(|session| !session.live) else { return; };
        let current = session.timeline.map(|timeline| {
            if timeline.rate > 0.0 { timeline.rate } else { timeline.resume_rate }
        }).unwrap_or(1.0);
        let next = RATES
            .iter()
            .copied()
            .rev()
            .find(|rate| *rate < current - 0.001)
            .unwrap_or(*RATES.last().unwrap());
        if session.set_playback_speed(Instant::now(), next).is_ok() {
            self.console_status = format!("DEMO SPEED: {next}X");
            self.publish_transient_ui();
        }
    }

    fn seek_demo_scrub_fraction(&mut self, fraction: f32, now: Instant) -> Result<(), String> {
        let (sample, elapsed) = {
            let session = self
                .game_session
                .as_mut()
                .filter(|session| !session.live)
                .ok_or_else(|| "NO DEMO SESSION".to_owned())?;
            let duration = session
                .demo_duration_ms()
                .ok_or_else(|| "DEMO TIMELINE IS NOT READY".to_owned())?;
            let elapsed = (duration as f32 * fraction.clamp(0.0, 1.0)).round() as i32;
            (session.seek_demo(now, elapsed)?, elapsed)
        };
        self.restore_demo_transients(elapsed, now);
        self.third_person_camera = ThirdPersonCameraState::default();
        self.apply_demo_view(sample, Duration::ZERO);
        self.previous_tick = now;
        Ok(())
    }

    fn begin_demo_scrub(&mut self, fraction: f32) {
        let Some(session) = self.game_session.as_mut().filter(|session| !session.live) else { return; };
        self.demo_scrub_resume_rate = session.playback_rate().unwrap_or(0.0);
        let now = Instant::now();
        session.set_audio_suppressed(true);
        let _ = session.set_playback_rate(now, 0.0);
        self.demo_scrub_dragging = true;
        let fraction = fraction.clamp(0.0, 1.0);
        self.demo_scrub_fraction = Some(fraction);
        self.demo_scrub_last_seek = Some(now);
        match self.seek_demo_scrub_fraction(fraction, now) {
            Ok(()) => self.demo_scrub_last_applied_fraction = Some(fraction),
            Err(error) => {
                self.console_status = format!("DEMO SEEK ERROR: {error}");
                self.push_console_line(format!("^1{}", self.console_status));
            }
        }
        self.publish_transient_ui();
    }

    fn update_demo_scrub(&mut self, x: f64) {
        if !self.demo_scrub_dragging {
            return;
        }
        let Some(size) = self.window.as_ref().map(|window| window.inner_size()) else { return; };
        let Some(layout) = ui::demo_timeline_layout(size.width, size.height) else { return; };
        let fraction = ((x as f32 - layout.track[0]) / layout.track[2]).clamp(0.0, 1.0);
        self.demo_scrub_fraction = Some(fraction);

        // The real seek happens from `tick_demo_scrub_preview`: winit can deliver
        // many CursorMoved events in one turn, so keeping only this latest target
        // truly coalesces them instead of replaying stale intermediate positions.
        self.publish_transient_ui();
    }

    fn tick_demo_scrub_preview(&mut self, now: Instant) {
        if !self.demo_scrub_dragging {
            return;
        }
        let Some(fraction) = self.demo_scrub_fraction else { return; };
        if self.demo_scrub_last_applied_fraction
            .is_some_and(|applied| (applied - fraction).abs() <= f32::EPSILON)
        {
            return;
        }
        let due = self
            .demo_scrub_last_seek
            .is_none_or(|last| now.saturating_duration_since(last) >= DEMO_SCRUB_PREVIEW_INTERVAL);
        if !due {
            return;
        }
        self.demo_scrub_last_seek = Some(now);
        match self.seek_demo_scrub_fraction(fraction, now) {
            Ok(()) => self.demo_scrub_last_applied_fraction = Some(fraction),
            Err(error) => {
                self.console_status = format!("DEMO SEEK ERROR: {error}");
                self.push_console_line(format!("^1{}", self.console_status));
            }
        }
    }

    fn finish_demo_scrub(&mut self) {
        if !self.demo_scrub_dragging {
            return;
        }
        self.demo_scrub_dragging = false;
        let fraction = self.demo_scrub_fraction.take().unwrap_or(0.0).clamp(0.0, 1.0);
        self.demo_scrub_last_seek = None;
        self.demo_scrub_last_applied_fraction = None;
        let now = Instant::now();
        let seek_result = self.seek_demo_scrub_fraction(fraction, now);
        if let Some(session) = self.game_session.as_mut().filter(|session| !session.live) {
            // The exact release seek is silent too. Only after we are settled at
            // the final destination do we allow audio presentation again.
            session.set_audio_suppressed(false);
            if seek_result.is_ok() && self.demo_scrub_resume_rate > 0.0 {
                let _ = session.set_playback_rate(now, self.demo_scrub_resume_rate);
            }
        }
        if let Err(error) = seek_result {
            self.console_status = format!("DEMO SEEK ERROR: {error}");
            self.push_console_line(format!("^1{}", self.console_status));
        }
        self.publish_transient_ui();
    }

    fn seek_demo_relative(&mut self, delta_ms: i32) {
        let now = Instant::now();
        let result = self.game_session.as_mut().and_then(|session| {
            if session.live { return None; }
            let current = session.demo_elapsed_ms(now)?.round() as i32;
            Some(session.seek_demo(now, current.saturating_add(delta_ms)))
        });
        if let Some(Ok(sample)) = result {
            let elapsed = self.game_session.as_ref().and_then(|session| session.demo_elapsed_ms(now)).unwrap_or(0.0).round() as i32;
            self.restore_demo_transients(elapsed, now);
            self.third_person_camera = ThirdPersonCameraState::default();
            self.apply_demo_view(sample, Duration::ZERO);
            self.previous_tick = now;
            self.publish_transient_ui();
        } else if let Some(Err(error)) = result {
            self.console_status = format!("DEMO SEEK ERROR: {error}");
            self.push_console_line(format!("^1{}", self.console_status));
        }
    }

    fn set_capture(&mut self, captured: bool) {
        if !captured {
            self.noclip_primary_down = false;
            self.noclip_alt_down = false;
        }
        if self.captured == captured {
            return;
        }
        let Some(window) = &self.window else {
            return;
        };
        if captured && self.overlay == OverlayMode::None {
            let grabbed = window
                .set_cursor_grab(CursorGrabMode::Locked)
                .or_else(|_| window.set_cursor_grab(CursorGrabMode::Confined));
            if grabbed.is_ok() {
                window.set_cursor_visible(false);
                self.captured = true;
            }
        } else {
            let _ = window.set_cursor_grab(CursorGrabMode::None);
            window.set_cursor_visible(true);
            self.captured = false;
        }
    }

    fn sync_profile_preview_mode(&mut self, active: bool) {
        if self.profile_preview_active == active {
            return;
        }
        self.profile_preview_active = active;
        if active {
            self.profile_name_input = self.network.name.clone();
            self.profile_preview_started = Instant::now();
        }
        self.profile_force_preview_pending = None;
        self.profile_force_preview_active = None;
        self.profile_force_preview_started = Instant::now();
        self.profile_preview_key = None;
        self.asset_preview_viewport_key = None;
        self.render_command(RenderCommand::SetAssetPreviewMode(active));
        self.render_command(RenderCommand::SetAssetPreviewViewport(None));
        if !active {
            self.profile_dynamic_models = Arc::new(Vec::new());
        }
    }

    fn set_overlay(&mut self, overlay: OverlayMode) {
        let leaving_console =
            self.overlay == OverlayMode::Console && overlay != OverlayMode::Console;
        self.overlay = overlay;
        self.sync_profile_preview_mode(
            !self.front_end && self.overlay == OverlayMode::Game && self.menu_selected == 2,
        );
        self.egui_repaint_requested = true;
        if leaving_console {
            self.console_input.clear();
            self.console_cursor = 0;
            self.console_history_index = None;
        }
        if overlay != OverlayMode::Console {
            self.console_search_open = false;
        }
        self.mouse_delta = (0.0, 0.0);
        self.last_mouse_motion_at = None;
        self.pending_mouse_input = None;
        if let Some(player) = &mut self.local_server {
            player.pause();
        }
        if overlay != OverlayMode::None {
            self.keys.clear();
            self.movement_keys.clear();
            self.mouse_buttons_down.clear();
            self.noclip_primary_down = false;
            self.noclip_alt_down = false;
            self.set_capture(false);
        } else if self.demo_playback_active() {
            self.set_capture(false);
        } else {
            self.set_capture(true);
        }
        self.publish_ui();
    }

    fn controls_page_active(&self) -> bool {
        self.overlay == OverlayMode::Game
            && if self.front_end {
                self.frontend_page == FrontendPage::Controls
            } else {
                self.menu_selected == 3
                    || (self.menu_selected == 6
                        && self.ui_mod() == Some(crate::net::mod_support::ServerMod::Japro))
            }
    }

    fn overlay_after_console(&self) -> OverlayMode {
        if self.front_end && self.overlay_before_console == OverlayMode::None {
            OverlayMode::Game
        } else {
            self.overlay_before_console
        }
    }

    fn frontend_back(&mut self) {
        if !self.front_end {
            return;
        }
        if self.overlay == OverlayMode::Video {
            self.frontend_page = FrontendPage::Main;
            self.set_overlay(OverlayMode::Game);
            return;
        }
        if self.frontend_page == FrontendPage::AssetViewer {
            self.render_command(RenderCommand::SetAssetPreviewMode(false));
            self.render_command(RenderCommand::SetAssetPreviewViewport(None));
            self.asset_preview_viewport_key = None;
            self.clear_asset_preview_runtime();
        }
        self.frontend_page = match self.frontend_page {
            FrontendPage::Main => FrontendPage::Main,
            FrontendPage::Play | FrontendPage::Controls | FrontendPage::DeveloperTools => FrontendPage::Main,
            FrontendPage::ServerBrowser | FrontendPage::SoloGame | FrontendPage::PlayDemo => FrontendPage::Play,
            FrontendPage::AssetViewer | FrontendPage::MapViewer => FrontendPage::DeveloperTools,
        };
        self.egui_repaint_requested = true;
        self.publish_ui();
    }

    fn mark_config_dirty(&mut self) {
        self.config_dirty = true;
        self.last_config_write = Instant::now();
    }

    fn refresh_bound_state(&mut self) {
        let mut movement_keys = HashSet::with_capacity(8);
        let mut primary = false;
        let mut alt = false;
        let mut live_buttons = HashSet::new();

        let mut apply = |binding: &str| {
            for command in keybinds::split_binding_commands(binding) {
                let verb = command.split_whitespace().next().unwrap_or("");
                if verb.starts_with('+') {
                    live_buttons.insert(verb.to_ascii_lowercase());
                }
                match verb.to_ascii_lowercase().as_str() {
                    "+forward" => { movement_keys.insert(KeyCode::KeyW); }
                    "+back" => { movement_keys.insert(KeyCode::KeyS); }
                    "+moveleft" => { movement_keys.insert(KeyCode::KeyA); }
                    "+moveright" => { movement_keys.insert(KeyCode::KeyD); }
                    "+moveup" => { movement_keys.insert(KeyCode::Space); }
                    "+movedown" => { movement_keys.insert(KeyCode::ControlLeft); }
                    "+speed" => { movement_keys.insert(KeyCode::ShiftLeft); }
                    "+attack" => primary = true,
                    "+altattack" => alt = true,
                    _ => {}
                }
            }
        };

        for code in &self.keys {
            if let Some(binding) = self.bindings.get(keybinds::bind_key_for_code(*code)) {
                apply(binding);
            }
        }
        for button in &self.mouse_buttons_down {
            if let Some(binding) = self.bindings.get(BindKey::Mouse(*button)) { apply(binding); }
        }

        let was_scores_showing = self.scores_showing;
        let was_zoomed = self.live_buttons.contains("+zoom");
        let is_zoomed = live_buttons.contains("+zoom");
        if is_zoomed != was_zoomed {
            // TaystJK CG_ZoomDown_f / CG_ZoomUp_f record cg.zoomTime when the
            // held +zoom state changes; keep the same transition epoch here.
            self.japro_zoom_transition_at = Some(Instant::now());
        }
        self.movement_keys = movement_keys;
        self.live_buttons = live_buttons;
        self.noclip_primary_down = primary;
        self.noclip_alt_down = alt;
        self.scores_showing = self.live_buttons.contains("+scores");
        if self.scores_showing && !was_scores_showing {
            // CG_ScoresDown_f clears stale contents when issuing a new request.
            self.request_scores_if_due(true);
        }
        if self.scores_showing != was_scores_showing {
            self.publish_ui();
        }
    }

    /// Whether `code` is currently bound to the `trace` command, so
    /// `route_egui_window_event` can let it fall through to the raw keybind
    /// dispatch instead of being swallowed as "a menu is open" input while
    /// the Trace popup is up — the same key needs to close it again.
    fn key_bound_to_trace(&self, code: KeyCode) -> bool {
        self.bindings
            .get(keybinds::bind_key_for_code(code))
            .is_some_and(|binding| keybinds::binding_contains_command(binding, "trace"))
    }

    fn execute_binding_press(&mut self, key: BindKey) {
        let Some(binding) = self.bindings.get(key).map(str::to_owned) else { return; };
        let mut buffered = Vec::new();
        for command in keybinds::split_binding_commands(&binding) {
            if command.starts_with('+') {
                // +scores is a local CG kbutton, not a usercmd button bit. The
                // held state is derived by refresh_bound_state above.
                if command
                    .split_whitespace()
                    .next()
                    .is_some_and(|verb| verb.eq_ignore_ascii_case("+scores"))
                {
                    continue;
                }
                // IN_KeyDown wasPressed: a tap shorter than a frame still fires.
                if let Some(verb) = command.split_whitespace().next() {
                    self.live_input.note_pressed(verb);
                }
                continue;
            }
            buffered.push(command.to_owned());
        }
        // Non-button commands use the same Cbuf path as console scripts, so a
        // binding like `echo one; wait; echo two` observes frame-aware wait.
        self.append_console_commands(buffered);
    }

    fn bind_control_key(&mut self, key: BindKey) {
        let Some(action) = keybinds::control_action(self.controls_selected) else { return; };
        let command = action.command;
        self.bindings.unbind_command(command);
        self.bindings.set(key, command);
        self.controls_waiting_for_key = false;
        self.refresh_bound_state();
        self.mark_config_dirty();
        self.console_status = format!("BOUND {} TO {}", keybinds::key_name(key), command);
        self.publish_ui();
    }

    fn unbind_selected_control(&mut self) {
        if let Some(action) = keybinds::control_action(self.controls_selected) {
            let command = action.command;
            if self.bindings.unbind_command(command) > 0 {
                self.refresh_bound_state();
                self.mark_config_dirty();
            }
        }
        self.controls_waiting_for_key = false;
        self.publish_ui();
    }

    fn handle_bind_console_command(&mut self, command: &str) -> bool {
        let words = keybinds::split_command_words(command.trim_start_matches('/'));
        let Some(verb) = words.first() else { return false; };
        if verb.eq_ignore_ascii_case("bind") {
            match words.as_slice() {
                [_] => self.push_console_line("^3bind <key> [command]^7 - attach a command to a key"),
                [_, key_name] => match keybinds::parse_key(key_name) {
                    Some(key) => match self.bindings.get(key).map(str::to_owned) {
                        Some(binding) => self.push_console_line(format!("^7\"{}\" = \"{}\"", keybinds::key_name(key), binding)),
                        None => self.push_console_line(format!("^7\"{}\" is not bound", keybinds::key_name(key))),
                    },
                    None => self.push_console_line(format!("^1\"{key_name}\" isn't a valid key")),
                },
                [_, key_name, rest @ ..] => match keybinds::parse_key(key_name) {
                    Some(key) => {
                        self.bindings.set(key, rest.join(" "));
                        self.refresh_bound_state();
                        self.mark_config_dirty();
                    }
                    None => self.push_console_line(format!("^1\"{key_name}\" isn't a valid key")),
                },
                [] => unreachable!(),
            }
            self.publish_ui();
            return true;
        }
        if verb.eq_ignore_ascii_case("unbind") {
            if words.len() != 2 {
                self.push_console_line("^3unbind <key>^7 - remove a key binding");
            } else if let Some(key) = keybinds::parse_key(&words[1]) {
                self.bindings.unbind(key);
                self.refresh_bound_state();
                self.mark_config_dirty();
            } else {
                self.push_console_line(format!("^1\"{}\" isn't a valid key", words[1]));
            }
            self.publish_ui();
            return true;
        }
        if verb.eq_ignore_ascii_case("unbindall") {
            self.bindings.clear();
            self.refresh_bound_state();
            self.mark_config_dirty();
            self.publish_ui();
            return true;
        }
        if verb.eq_ignore_ascii_case("bindlist") {
            for (key, binding) in self.bindings.sorted() {
                self.push_console_line(format!("^7{} \"{}\"", keybinds::key_name(key), binding));
            }
            return true;
        }
        false
    }

    fn flush_config(&mut self) {
        if !self.config_dirty {
            return;
        }

        // Restart-sensitive settings are latched. Never persist a merely selected
        // resolution/fullscreen/backend, and never persist an unconfirmed mode.
        // If the process dies while the keep/revert dialog is visible, the next
        // launch therefore comes back in the last known-good video mode.
        let stable = self
            .video_confirmation
            .map(|confirmation| confirmation.previous)
            .or(self.pending_video_confirmation)
            .or_else(|| {
                self.pending_renderer_restart.map(|pending| {
                    if pending.confirm_on_change {
                        pending.previous
                    } else {
                        // A non-confirming restart is a rollback/recovery. Its
                        // target is already the last known-good mode.
                        pending.target
                    }
                })
            })
            .unwrap_or_else(|| self.applied_video_mode());
        let mut settings = self.video;
        settings.fullscreen = stable.fullscreen;
        settings.renderer_backend = stable.renderer_backend;
        settings.resolution = stable.resolution;
        // Grass/ocean can be disabled live. Preserve a pending enable as latched
        // until the renderer has actually been restarted with the required map
        // resources, but persist live disables immediately.
        settings.grass = if self.video.grass && !self.applied_grass {
            self.applied_grass
        } else {
            self.video.grass
        };
        settings.ocean = if self.video.ocean && !self.applied_ocean {
            self.applied_ocean
        } else {
            self.video.ocean
        };
        // OpenJK archives the pending CVAR_LATCH value. Overlay only console
        // latches here; unconfirmed menu display changes above remain last-good.
        self.apply_latched_values_to_settings(&mut settings);

        let presentation = config::ClientPresentationSettings {
            third_person: self.third_person,
            first_person_lightsaber: self.first_person_lightsaber,
            saber_trail: self.saber_trail,
            smoothing: self.presentation_smoothing,
            mouse: self.mouse_input,
            fov: self.camera.cg_fov(),
            model: self.solo_client_info.model_cvar(),
            force_model: self.force_model.clone(),
            crosshair: self.crosshair,
            hud_layout: self.hud_layout,
            movement_keys: self.movement_keys_hud,
            strafe_helper: self.strafe_helper,
            console_timestamps: self.console_timestamps,
            console_suggest: self.console_suggest,
            chatbox_completion: self.chatbox_completion,
            ui_vgs: self.ui_vgs,
            jump_height_shade: self.jump_height_shade,
            screen_shake: self.screen_shake,
            zoom_fov: self.japro_zoom_fov,
            fk_duration: self.japro_fk_duration,
            fk_first_jump_duration: self.japro_fk_first_jump_duration,
            fk_second_jump_delay: self.japro_fk_second_jump_delay,
            network: self.network.clone(),
            japro: self.japro_cg,
            master_servers: self.server_browser.master_servers.clone(),
        };
        match config::save_video_settings(
            &self.config_path,
            settings,
            &self.bindings,
            &presentation,
            &self.audio,
        ) {
            Ok(()) => self.config_dirty = false,
            Err(error) => eprintln!("Config save failed: {error}"),
        }
    }

    /// Refresh rate of the monitor the window is on, in Hz.
    fn monitor_refresh_hz(&self) -> Option<f64> {
        let hz = self
            .window
            .as_ref()?
            .current_monitor()?
            .refresh_rate_millihertz()? as f64
            / 1000.0;
        (hz >= 1.0).then_some(hz)
    }

    /// Highest FPS the present path can actually reach, when something other than
    /// the GPU is the limit.
    ///
    /// Only DX12 with FAST vsync has one: wgpu presents Mailbox without the DXGI
    /// tearing flag, so presents retire at vblank and at most
    /// `r_maxFrameLatency` frames can retire per refresh. VSync OFF
    /// (Immediate) sets the tearing flag and is uncapped, ON/Adaptive are
    /// refresh-bound by definition on every backend, and Vulkan's Mailbox lets
    /// the app render ahead freely.
    fn present_fps_ceiling(&self) -> Option<u32> {
        if self.applied_renderer_backend != RendererBackend::Dx12
            || self.video.vsync != VsyncMode::Fast
        {
            return None;
        }
        let refresh = self.monitor_refresh_hz()?;
        Some((refresh * f64::from(self.video.max_frame_latency)) as u32)
    }

    /// Highest cap that means anything here: the DX12 FAST present ceiling when
    /// there is one, otherwise the cvar's own maximum.
    fn fps_cap_limit(&self) -> u32 {
        self.present_fps_ceiling()
            .unwrap_or(config::FPS_CAP_MAX)
    }

    /// Resolve a requested cap to the number that will actually be honoured.
    ///
    /// "Unlimited" is not shown as 0 anywhere, because 0 tells the player nothing
    /// about the frame rate they will get. It resolves to whatever the real limit
    /// is, so the displayed cap is always the true one on every backend and vsync
    /// mode rather than only on the DX12 path that has a hard ceiling.
    fn resolved_fps_cap(&self, requested: u32) -> u32 {
        let limit = self.fps_cap_limit();
        if requested == 0 || requested > limit {
            limit
        } else {
            requested
        }
    }

    fn effective_fps_cap(&self) -> u32 {
        self.resolved_fps_cap(self.video.fps_cap)
    }

    fn frontend_refresh_fps_cap(&self) -> Option<u32> {
        self.monitor_refresh_hz().map(|hz| hz.round().clamp(1.0, u32::MAX as f64) as u32)
    }

    fn active_render_fps_cap(&self) -> u32 {
        if self.front_end {
            // The menu follows the monitor, but never runs faster than com_maxfps.
            let cap = self.effective_fps_cap();
            self.frontend_refresh_fps_cap().map_or(cap, |refresh| refresh.min(cap))
        } else {
            self.effective_fps_cap()
        }
    }

    fn sync_render_fps_cap(&self) {
        self.render_command(RenderCommand::SetFpsCap(self.active_render_fps_cap()));
    }

    fn set_fps_cap(&mut self, fps_cap: u32) {
        let requested = fps_cap;
        let fps_cap = self.resolved_fps_cap(requested);
        // Only the DX12 present ceiling is worth explaining. Rounding 0 or an
        // over-range number down to the cvar maximum is not a surprise.
        if let Some(ceiling) = self.present_fps_ceiling() {
            if requested > ceiling {
                self.console_status = format!(
                    "DX12 + FAST VSYNC TOPS OUT AT {ceiling} FPS ({} FRAMES x {:.0} HZ); \
                     CAP SNAPPED BACK. USE VSYNC OFF FOR UNCAPPED.",
                    self.video.max_frame_latency,
                    self.monitor_refresh_hz().unwrap_or_default()
                );
                self.push_console_line(format!("^3{}", self.console_status));
            }
        }
        self.video.fps_cap = fps_cap;
        if !self.fps_cap_editing {
            self.fps_cap_input = fps_cap.to_string();
        }
        self.sync_render_fps_cap();
        self.mark_config_dirty();
        self.publish_ui();
    }

    fn set_max_frame_latency(&mut self, latency: u32) {
        let latency = latency.clamp(1, 3);
        if self.video.max_frame_latency == latency {
            return;
        }
        self.video.max_frame_latency = latency;
        self.render_command(RenderCommand::SetMaxFrameLatency(latency));
        self.mark_config_dirty();

        // DX12 + FAST has a real present-rate ceiling proportional to the
        // configured frame queue. Update the active cap without rewriting the
        // user's requested com_maxfps so A/B switching remains reversible.
        self.sync_render_fps_cap();
        self.console_status = format!(
            "MAX FRAME LATENCY: {latency} ({})",
            match latency {
                1 => "LOWEST LATENCY",
                2 => "BALANCED",
                _ => "MAXIMUM THROUGHPUT",
            }
        );
        self.publish_ui();
    }

    fn begin_fps_cap_edit(&mut self) {
        if !self.fps_cap_editing {
            self.fps_cap_editing = true;
            self.fps_cap_input = self.video.fps_cap.to_string();
            self.fps_cap_replace_on_type = true;
        }
        self.publish_ui();
    }

